function renderizarVistaActual() {
    pendingRealtimeRender = false;
    clearTimeout(realtimeResumeTimer);
    realtimeResumeTimer = null;
    // Persistir la vista actual para sobrevivir F5
    try { localStorage.setItem('planify_vista', String(vistaActual || '')); }
    catch (e) { /* noop */ }
    // Limpiar contenido
    mainContent.innerHTML = '';
    document.body.dataset.view = vistaActual;
    document.body.dataset.role = estado.usuarioActual || 'visita';
    const syncStrip = document.getElementById('sync-status-strip');
    const searchToolbar = document.getElementById('search-container');
    const searchOverlay = document.getElementById('search-results-overlay');
    const ocultarChromeGlobal = true;
    if (syncStrip) syncStrip.style.display = ocultarChromeGlobal ? 'none' : '';
    if (searchToolbar) searchToolbar.style.display = ocultarChromeGlobal ? 'none' : '';
    if (ocultarChromeGlobal && searchOverlay) searchOverlay.style.display = 'none';
    
    // Actualizar clases activas en nav
    Object.keys(navConfig).forEach(id => {
        const btn = document.getElementById(id);
        if (btn) btn.classList.toggle('active', navConfig[id] === vistaActual);
    });

    // Renderizar según estado
    switch (vistaActual) {
        case 'control':
            renderControlView();
            break;
        case 'checkin':
            renderCheckInView();
            break;
        case 'dashboard':
            renderDashboardView();
            break;
        case 'trabajadores':
            renderTrabajadoresView();
            break;
        case 'historial':
            renderHistorialView(true);
            break;
        case 'equipos':
            renderEquiposView();
            break;
        case 'semanal':
            renderSemanalView();
            break;
        case 'rutas':
            renderRutasView();
            break;
        case 'termografia':
            renderTermografiaView();
            break;
        case 'trabajador-rutas':
            renderTrabajadorRutasView();
            break;
        case 'trabajador-ruta-detalle':
            renderTrabajadorRutaDetalle();
            break;
        case 'ito':
            renderItoView();
            break;
        case 'avisos-sap':
            if (typeof window.renderAvisosSapView === 'function') {
                window.renderAvisosSapView();
            } else {
                mainContent.innerHTML = '<div class="panel" style="margin:1rem;padding:1.2rem;"><p>El módulo Avisos SAP aún no carga. Recarga la página.</p></div>';
            }
            break;
        case 'mis_horas':
            renderMisHorasView();
            break;
        case 'horas_extra_admin':
            renderHorasExtraAdminView();
            break;
        case 'insumos':
            renderInsumosView();
            break;
        case 'perfil':
            renderPerfilView();
            break;
    }

    // (El menú móvil no se cierra automáticamente al navegar)
}

// Navegación programática a una vista (mismo efecto que clickear el nav):
// cambia la vista activa, resetea el sub-estado de la sección y re-renderiza.
// La usan paneles como el de Rutas en Control (botón "Ver rutas").
window.mostrarVista = function(vista) {
    if (!vista) return;
    vistaActual = vista;
    if (vista === 'rutas') {
        vistaRutasEstado.seccionActiva = '';
        vistaRutasEstado.rutaActivaIdx = null;
    }
    if (vista === 'termografia') {
        vistaTermografiaEstado.seccion = null;
        vistaTermografiaEstado.equipoKey = null;
        vistaTermografiaEstado.registroId = null;
    }
    renderizarVistaActual();
};

