function getTareasRelacionadasFicha(equipo, siblingIds) {
    const ids = new Set([...siblingIds].map(String));
    const normalizarTextoFicha = valor => String(valor || '')
        .normalize('NFD').replace(/[\u0300-\u036f]/g, '')
        .toUpperCase();
    const textoEquipoFicha = normalizarTextoFicha([
        equipo.activo,
        equipo.componente,
        equipo.denominacion_ut,
        equipo.kks,
        equipo.ubicacion_tecnica
    ].filter(Boolean).join(' '));
    const utEquipo = String(equipo.ubicacion_tecnica || equipo.kks || '').trim().toUpperCase();
    const esEquipoBbaAceite = BAE_KKS.has(utEquipo)
        || textoEquipoFicha.includes('BOMBA ACEITE EMERGENCIA')
        || textoEquipoFicha.includes('BBA ACEITE EMERGENCIA')
        || textoEquipoFicha.includes('BBA ACEITE D.C')
        || textoEquipoFicha.includes('ESCOBILLA');

    const tareasNormales = (estado.historialTareas || [])
        .filter(task => {
            if (task.equipo_id && ids.has(String(task.equipo_id))) return true;
            const tipo = String(task.tipo || '').toLowerCase();
            const mismaUnidad = tipo.includes(`[${String(equipo.ubicacion || '').toLowerCase()}]`) || (task.ubicacion && task.ubicacion === equipo.ubicacion);
            if (tipo.includes(String(equipo.activo || '').toLowerCase()) && mismaUnidad) return true;

            const textoTask = normalizarTextoFicha([task.tipo, task.subtitulo, task.ubicacion].filter(Boolean).join(' '));
            const esTaskBbaAceite = textoTask.includes('BOMBA ACEITE EMERGENCIA')
                || textoTask.includes('BBA ACEITE EMERGENCIA')
                || textoTask.includes('BBA ACEITE D.C')
                || textoTask.includes('MOTOR BBA ACEITE D.C');
            return esEquipoBbaAceite && esTaskBbaAceite && mismaUnidad;
        });

    let historialRutas = [];
    try { historialRutas = JSON.parse(localStorage.getItem('planify_rutas_historial') || '[]'); } catch (e) {}

    const rutasRelacionadas = (historialRutas || [])
        .filter(item => {
            if (!item || (item.unidad && item.unidad !== equipo.ubicacion)) return false;
            const ruta = typeof RUTAS_VIBRACION_SEED !== 'undefined' ? RUTAS_VIBRACION_SEED[item.rutaIdx] : null;
            const textoRuta = normalizarTextoFicha(item.rutaNombre || '');
            if (esEquipoBbaAceite && (
                textoRuta.includes('BOMBA ACEITE EMERGENCIA') ||
                textoRuta.includes('BBA ACEITE EMERGENCIA') ||
                textoRuta.includes('BBA ACEITE D.C') ||
                textoRuta.includes('MOTOR BBA ACEITE D.C')
            )) return true;
            if (!ruta || !utEquipo) return String(item.rutaNombre || '').toLowerCase().includes(String(equipo.activo || '').toLowerCase());
            return (ruta.equipos || []).some(eqRuta =>
                (eqRuta.componentes || []).some(compRuta =>
                    String(compRuta.ubicacion_tecnica || '').trim().toUpperCase() === utEquipo
                )
            );
        })
        .map(item => ({
            ...item,
            tipo: item.rutaNombre || 'Ruta cerrada',
            ubicacion: item.unidad || equipo.ubicacion,
            created_at: item.fechaCierre || item.fechaInicio || null,
            fecha_termino: item.fechaCierre || null,
            fecha_inicio: item.fechaInicio || null,
            lider_nombre: item.liderNombre || item.lider_nombre || '',
            ayudantes_nombres: item.tecnicosNombres || item.tecnicos_nombres || []
        }));

    return [...tareasNormales, ...rutasRelacionadas]
        .sort((a, b) => new Date(b.created_at || b.fecha_termino || b.fecha_inicio || 0) - new Date(a.created_at || a.fecha_termino || a.fecha_inicio || 0))
        .slice(0, 8);
}

function renderFichaLoadingState(equipo) {
    if (!document.getElementById('ficha-equipo-breadcrumb') || !document.getElementById('ficha-equipo-overview')) {
        document.getElementById('modal-ficha-tecnica')?.remove();
        renderFichaTecnicaModal();
    }
    if (!document.getElementById('ficha-equipo-breadcrumb') || !document.getElementById('ficha-equipo-overview')) return;
    document.getElementById('ficha-equipo-nombre').textContent = `${equipo.activo}${equipo.componente ? ' · ' + equipo.componente : ''}`;
    document.getElementById('ficha-equipo-ubicacion').textContent = equipo.ubicacion || 'Sin ubicación';
    document.getElementById('ficha-equipo-kks').textContent = equipo.kks || 'N/A';
    document.getElementById('ficha-equipo-breadcrumb').innerHTML = `<span>Control</span><i class="fa-solid fa-angle-right"></i><span>${equipo.ubicacion || 'Sin unidad'}</span><i class="fa-solid fa-angle-right"></i><strong>${equipo.activo}</strong>`;
    document.getElementById('ficha-equipo-overview').innerHTML = `<div class="planify-ficha-empty planify-ficha-loading" style="grid-column:1 / -1;"><div><div style="font-weight:800;color:#0f172a;margin-bottom:.35rem;">Cargando condición del activo...</div><div style="font-size:.85rem;line-height:1.5;">Recopilando mediciones, historial y componentes relacionados.</div></div></div>`;
    document.getElementById('ficha-resumen-vibracion').innerHTML = emptyFichaState('Preparando tendencia', 'Se están consolidando las mediciones de vibración.');
    document.getElementById('ficha-resumen-termografia').innerHTML = emptyFichaState('Preparando tendencia', 'Se están consolidando las mediciones térmicas.');
    document.getElementById('lista-mediciones-vibracion').innerHTML = emptyFichaState('Cargando vibraciones', 'En unos segundos verás las últimas lecturas.');
    document.getElementById('lista-mediciones-termografia').innerHTML = emptyFichaState('Cargando termografía', 'En unos segundos verás las últimas inspecciones.');
    document.getElementById('lista-mediciones-lubricacion').innerHTML = emptyFichaState('Cargando actividad de lubricación', 'Buscando cambios de aceite y registros asociados.');
    document.getElementById('ficha-actividad-trabajos').innerHTML = emptyFichaState('Cargando historial', 'Revisando los últimos cierres relacionados con este activo.');
    document.getElementById('ficha-componentes-relacionados').innerHTML = emptyFichaState('Cargando componentes', 'Buscando componentes del mismo activo dentro de la unidad.');
}

function getNombresTecnicosFicha(source) {
    if (!source) return [];
    const normalizarLista = valor => {
        if (Array.isArray(valor)) return valor;
        if (typeof valor === 'string') return valor.split(',');
        return [];
    };
    const directos = [
        ...normalizarLista(source.tecnicos_nombres),
        ...normalizarLista(source.tecnicosNombres),
        ...normalizarLista(source.ayudantes_nombres),
        ...normalizarLista(source.ayudantesNombres)
    ];
    if (source.tecnico_nombre) directos.push(...String(source.tecnico_nombre).split(','));
    if (source.tecnicoNombre) directos.push(...String(source.tecnicoNombre).split(','));
    const limpios = directos.map(nombre => String(nombre || '').trim()).filter(Boolean);
    if (limpios.length) return [...new Set(limpios)];
    const lider = source.lider_nombre || source.liderNombre;
    return lider ? [String(lider).trim()].filter(Boolean) : [];
}

const TECNICOS_BOMBAS_EMERGENCIA_FICHA = ['Diego Campillay', 'Ana Baez'];

function esBombaEmergenciaFicha(equipo) {
    const texto = [
        equipo?.activo,
        equipo?.componente,
        equipo?.denominacion_ut,
        equipo?.ubicacion_tecnica,
        equipo?.kks,
        equipo?.ruta
    ].filter(Boolean).join(' ').toLowerCase();
    return /(bomba|bba|bbas)/i.test(texto) && /emerg/i.test(texto);
}

function completarTecnicosBombasEmergenciaFicha(mediciones, equipo) {
    if (!Array.isArray(mediciones) || !mediciones.length || !esBombaEmergenciaFicha(equipo)) return mediciones;
    return mediciones.map(medicion => {
        const tipo = String(medicion?.tipo || '').toLowerCase();
        if (!['vibracion', 'termografia'].includes(tipo) || getNombresTecnicosFicha(medicion).length) return medicion;
        return {
            ...medicion,
            tecnico_nombre: TECNICOS_BOMBAS_EMERGENCIA_FICHA.join(', '),
            tecnicos_nombres: TECNICOS_BOMBAS_EMERGENCIA_FICHA
        };
    });
}

function fechaClaveFicha(valor) {
    if (!valor) return '';
    const texto = String(valor);
    const match = texto.match(/^(\d{4}-\d{2}-\d{2})/);
    if (match) return match[1];
    const fecha = new Date(texto);
    return Number.isNaN(fecha.getTime()) ? '' : fecha.toISOString().slice(0, 10);
}

// La tabla `mediciones` no guarda técnico. Pero las mediciones de ruta heredan
// el técnico de la EJECUCIÓN de ruta (lider/ayudante asignados). Aquí derivamos
// los técnicos de las ejecuciones (activas + historial) que cubren este equipo,
// agrupados por fecha, para mostrarlos en la ficha.
function _tecnicosRutaPorEquipoFicha(equipo) {
    const ut = String(equipo?.ubicacion_tecnica || equipo?.kks || '').trim().toUpperCase();
    if (!ut) return [];
    const seed = (typeof RUTAS_VIBRACION_SEED !== 'undefined') ? RUTAS_VIBRACION_SEED : [];
    const out = [];
    const procesar = (ej, rutaIdx) => {
        if (!ej) return;
        const r = seed[rutaIdx];
        if (!r) return;
        const cubre = (r.equipos || []).some(eq => (eq.componentes || []).some(c =>
            String(c.ubicacion_tecnica || '').trim().toUpperCase() === ut));
        if (!cubre) return;
        const tecnicos = (Array.isArray(ej.tecnicosNombres) && ej.tecnicosNombres.length)
            ? ej.tecnicosNombres.filter(Boolean)
            : [ej.liderNombre, ej.ayudanteNombre].filter(Boolean);
        if (!tecnicos.length) return;
        out.push({ fecha: fechaClaveFicha(ej.fechaCierre || ej.fechaInicio || ''), tecnicos });
    };
    const activas = (typeof getRutasEjecuciones === 'function') ? getRutasEjecuciones() : {};
    Object.entries(activas || {}).forEach(([idx, ej]) => procesar(ej, Number(idx)));
    let hist = [];
    try { hist = JSON.parse(localStorage.getItem('planify_rutas_historial') || '[]'); } catch (e) {}
    (hist || []).forEach(h => procesar(h, h.rutaIdx));
    return out;
}

function enriquecerMedicionesConRutaFicha(mediciones, equipo) {
    if (!Array.isArray(mediciones) || !mediciones.length) return mediciones;
    const fuentes = _tecnicosRutaPorEquipoFicha(equipo);
    if (!fuentes.length) return mediciones;
    return mediciones.map(m => {
        if (getNombresTecnicosFicha(m).length) return m;
        const fm = fechaClaveFicha(m.fecha);
        let src = fuentes.find(f => f.fecha && f.fecha === fm);
        if (!src && fuentes.length === 1) src = fuentes[0];
        if (!src) return m;
        return { ...m, tecnico_nombre: src.tecnicos.join(', '), tecnicos_nombres: src.tecnicos };
    });
}

function enriquecerMedicionesConTecnicosFicha(mediciones, tareasRelacionadas) {
    const tareas = Array.isArray(tareasRelacionadas) ? tareasRelacionadas : [];
    return (mediciones || []).map(medicion => {
        if (getNombresTecnicosFicha(medicion).length) return medicion;
        const fechaMed = fechaClaveFicha(medicion.fecha);
        const tareaMatch = tareas.find(task =>
            fechaMed &&
            [task.fecha_med, task.fecha_termino, task.created_at, task.fecha_inicio]
                .some(fecha => fechaClaveFicha(fecha) === fechaMed)
        ) || tareas[0];
        const tecnicos = getNombresTecnicosFicha(tareaMatch);
        if (!tecnicos.length) return medicion;
        return {
            ...medicion,
            tecnico_nombre: tecnicos.join(', '),
            tecnicos_nombres: tecnicos
        };
    });
}

function renderLecturaFicha(item, tipo) {
    const status = getEstadoCondicionFicha(tipo, item.valor);
    const isVib = tipo === 'vibracion';
    const tecnicosTexto = getNombresTecnicosFicha(item).join(', ') || 'Sin técnico';
    return `
        <article id="med-${item.id}" class="planify-ficha-reading ${status.tone}">
            <div class="planify-ficha-reading-top">
                <div>
                    <div class="planify-ficha-reading-title">${item.punto_medicion || item.componente || 'Punto general'}</div>
                    <div class="planify-ficha-reading-meta">
                        <span><i class="fa-regular fa-calendar"></i> ${formatearFechaHoraFicha(item.fecha)}</span>
                        <span><i class="fa-solid fa-user-gear"></i> ${escapeHtml(tecnicosTexto)}</span>
                    </div>
                </div>
                <div class="planify-ficha-reading-value ${isVib ? 'is-vib' : 'is-temp'}">${numeroFicha(item.valor, isVib ? 2 : 1)} ${item.unidad || (isVib ? 'mm/s' : '°C')}</div>
            </div>
            <div style="display:flex;justify-content:space-between;gap:.75rem;align-items:flex-start;">
                <div class="planify-ficha-reading-note">${item.observaciones || 'Sin observaciones registradas.'}</div>
                <div style="display:flex;flex-direction:column;align-items:flex-end;gap:.45rem;">
                    <span class="planify-status-badge ${status.className}"><i class="fa-solid fa-circle"></i> ${status.label}</span>
                    <button onclick="window._borrarMedicion('${item.id}')" title="Eliminar medición" style="background:none;border:none;cursor:pointer;color:#94a3b8;padding:2px 4px;font-size:0.84rem;line-height:1;" onmouseover="this.style.color='#ef4444'" onmouseout="this.style.color='#94a3b8'"><i class="fa-solid fa-trash"></i></button>
                </div>
            </div>
        </article>
    `;
}

function renderActividadFicha(task, equipo) {
    const fecha = task.created_at || task.fecha_termino || task.fecha_inicio;
    return `
        <article class="planify-ficha-task">
            <div class="planify-ficha-task-top">
                <div>
                    <div class="planify-ficha-task-title">${String(task.tipo || 'Trabajo registrado').replace(/^\s*\[[^\]]+\]\s*/, '').replace(/\s*\([^)]+\)\s*$/, '')}</div>
                    <div class="planify-ficha-task-meta">
                        <span><i class="fa-regular fa-calendar"></i> ${formatearFechaHoraFicha(fecha)}</span>
                        <span><i class="fa-solid fa-user-tie"></i> ${task.lider_nombre || 'Sin líder'}</span>
                    </div>
                </div>
                ${task.ot_numero ? `<span class="planify-ficha-chip"><i class="fa-solid fa-hashtag"></i> ${task.ot_numero}</span>` : ''}
            </div>
            <div class="planify-ficha-reading-note">${_accionesResumenHistorial(task.acciones_realizadas) || task.observaciones || 'Sin detalle operativo.'}</div>
            <div class="planify-ficha-task-meta">
                <span><i class="fa-regular fa-bell"></i> ${task.numero_aviso || 'Sin aviso'}</span>
                <span><i class="fa-solid fa-business-time"></i> ${task.hh_trabajo || '0'} HH</span>
                <button class="planify-ficha-link" onclick="window.irAHistorialDeEquipo('${equipo.id}')">Ver en historial</button>
            </div>
        </article>
    `;
}

function renderComponenteRelacionadoFicha(item, medicionesGrupo, siblingIds) {
    const ids = new Set([...siblingIds].map(String));
    const mismas = medicionesGrupo.filter(m => ids.has(String(m.equipo_id)) && String(m.equipo_id) === String(item.id));
    const vib = mismas.filter(m => m.tipo === 'vibracion').sort((a, b) => new Date(b.fecha) - new Date(a.fecha))[0] || null;
    const termo = mismas.filter(m => m.tipo === 'termografia').sort((a, b) => new Date(b.fecha) - new Date(a.fecha))[0] || null;
    const estados = [vib ? getEstadoCondicionFicha('vibracion', vib.valor) : null, termo ? getEstadoCondicionFicha('termografia', termo.valor) : null].filter(Boolean);
    const estado = estados.length ? consolidarEstadoFicha(estados) : { label: 'Sin datos', className: 'is-normal', tone: '' };
    return `
        <article class="planify-ficha-related">
            <div class="planify-ficha-related-main">
                <button class="planify-ficha-link" onclick="window.abrirFichaTecnica('${item.id}')">${item.componente || item.activo}</button>
                <span>${item.kks || 'Sin KKS'} · ${vib ? `Vib ${numeroFicha(vib.valor, 2)} mm/s` : 'Sin vib'} · ${termo ? `Temp ${numeroFicha(termo.valor, 1)} °C` : 'Sin termo'}</span>
            </div>
            <span class="planify-status-badge ${estado.className}"><i class="fa-solid fa-circle"></i> ${estado.label}</span>
        </article>
    `;
}

const TIRISTOR_PUNTOS_FICHA = ['x1', 'x2', 'y1', 'y2', 'z1', 'z2'];
const TIRISTOR_LABELS_FICHA = { x1: 'X1', x2: 'X2', y1: 'Y1', y2: 'Y2', z1: 'Z1', z2: 'Z2' };
const TIRISTOR_MODULOS_FICHA = ['x', 'y', 'z'];
const TIRISTOR_MODULO_LABELS_FICHA = { x: 'X', y: 'Y', z: 'Z' };
const TIRISTOR_MODULO_PUNTOS_FICHA = {
    x: { entrada: 'x1', salida1: 'x1', salida2: 'x2' },
    y: { entrada: 'y1', salida1: 'y1', salida2: 'y2' },
    z: { entrada: 'z1', salida1: 'z1', salida2: 'z2' }
};

function _tiristoresMedicionBase(id, hora, mw, nota, entradaXYZ, salidaPuntos, unidad = 'U3', extras = {}) {
    const [ex, ey, ez] = entradaXYZ;
    const [x1, x2, y1, y2, z1, z2] = salidaPuntos;
    return {
        id,
        unidad,
        hora,
        mw: String(mw),
        nota,
        entrada: { x1: ex, x2: ex, y1: ey, y2: ey, z1: ez, z2: ez },
        salida: { x1, x2, y1, y2, z1, z2 },
        ...extras,
        created_at: `2026-07-05T${hora || '00:00'}:00`
    };
}

