function _tiristoresUnidadEquipo(equipo) {
    const texto = [
        equipo?.activo,
        equipo?.componente,
        equipo?.ubicacion,
        equipo?.denominacion_ut,
        equipo?.kks,
        equipo?.ubicacion_tecnica
    ].filter(Boolean).join(' ')
        .normalize('NFD').replace(/[\u0300-\u036f]/g, '').toUpperCase();
    const unidad = (texto.match(/\bU\s?([35])\b/) || [])[1];
    if (!unidad) return '';
    if (!/(EXCITATRIZ|EXCITACION|TIRISTOR|RECTIFICADOR)/.test(texto)) return '';
    return `U${unidad}`;
}

function _tiristoresStoreLeer() {
    try {
        const data = JSON.parse(localStorage.getItem('planify_tiristores_excitatriz') || '{}');
        return data && typeof data === 'object' ? data : {};
    } catch (e) {
        return {};
    }
}

function _tiristoresLeerUnidad(unidad) {
    const store = _tiristoresStoreLeer();
    const tieneUnidadGuardada = Object.prototype.hasOwnProperty.call(store, unidad);
    const base = TIRISTORES_BASE_PDF[unidad] || [];
    const guardadas = tieneUnidadGuardada && Array.isArray(store[unidad]) ? store[unidad] : [];
    const idsGuardadas = new Set(guardadas.map(item => String(item?.id || '')));
    const lista = tieneUnidadGuardada
        ? (unidad === 'U5' ? [...base.filter(item => !idsGuardadas.has(String(item.id))), ...guardadas] : guardadas)
        : base;
    return lista
        .map(item => ({
            ...item,
            entrada: item.entrada || {},
            salida: item.salida || {},
            frente: item.frente || {},
            parametros: item.parametros || {}
        }))
        .filter(item => _tiristoresTieneDatos(item))
        .sort((a, b) => _tiristoresHoraMin(a.hora) - _tiristoresHoraMin(b.hora) || String(a.created_at || '').localeCompare(String(b.created_at || '')));
}

function _tiristoresGuardarUnidad(unidad, mediciones) {
    const store = _tiristoresStoreLeer();
    store[unidad] = (mediciones || []).filter(_tiristoresTieneDatos);
    localStorage.setItem('planify_tiristores_excitatriz', JSON.stringify(store));
}

function _tiristoresHoraMin(hora) {
    const m = String(hora || '').match(/^(\d{1,2}):(\d{2})$/);
    return m ? Number(m[1]) * 60 + Number(m[2]) : 99999;
}

function _tiristoresNumero(valor) {
    if (valor === null || valor === undefined || valor === '') return null;
    const n = Number(String(valor).replace(',', '.'));
    return Number.isFinite(n) ? n : null;
}

function _tiristoresOrdenMw(a, b) {
    const ma = _tiristoresNumero(a?.mw);
    const mb = _tiristoresNumero(b?.mw);
    const va = Number.isFinite(ma) ? ma : Number.POSITIVE_INFINITY;
    const vb = Number.isFinite(mb) ? mb : Number.POSITIVE_INFINITY;
    return va - vb
        || _tiristoresHoraMin(a?.hora) - _tiristoresHoraMin(b?.hora)
        || String(a?.created_at || '').localeCompare(String(b?.created_at || ''));
}

function _tiristoresOrdenHora(a, b) {
    return _tiristoresHoraMin(a?.hora) - _tiristoresHoraMin(b?.hora)
        || String(a?.created_at || '').localeCompare(String(b?.created_at || ''));
}

function _tiristoresRangoMw(lista = []) {
    const cargas = lista
        .map(item => _tiristoresNumero(item?.mw))
        .filter(v => Number.isFinite(v));
    return cargas.length ? { min: Math.min(...cargas), max: Math.max(...cargas) } : null;
}

function _tiristoresFiltrarPorRangoMw(lista = [], rango = null) {
    if (!rango) return lista;
    return lista.filter(item => {
        const mw = _tiristoresNumero(item?.mw);
        return Number.isFinite(mw) && mw >= rango.min - 0.001 && mw <= rango.max + 0.001;
    });
}

function _tiristoresMwUnicos(lista = []) {
    const valores = new Map();
    lista.forEach(item => {
        const mw = _tiristoresNumero(item?.mw);
        if (Number.isFinite(mw)) valores.set(mw.toFixed(3), mw);
    });
    return [...valores.values()].sort((a, b) => a - b);
}

function _tiristoresFiltrarBrechasComparacion(listaComparacion = [], listaActual = []) {
    const cargasActuales = _tiristoresMwUnicos(listaActual);
    if (cargasActuales.length < 2) return listaComparacion;
    return listaComparacion.filter(item => {
        const mw = _tiristoresNumero(item?.mw);
        if (!Number.isFinite(mw)) return true;
        return !cargasActuales.some((inicio, index) => {
            const fin = cargasActuales[index + 1];
            return Number.isFinite(fin) && mw > inicio + 0.001 && mw < fin - 0.001;
        });
    });
}

function _tiristoresLimitarComparacionPorConteoMw(listaComparacion = [], listaActual = []) {
    const disponibles = new Map();
    const cargasActuales = [];
    listaActual.forEach(item => {
        const mw = _tiristoresNumero(item?.mw);
        if (!Number.isFinite(mw)) return;
        cargasActuales.push(mw);
        const key = mw.toFixed(3);
        disponibles.set(key, (disponibles.get(key) || 0) + 1);
    });
    const maxActual = cargasActuales.length ? Math.max(...cargasActuales) : null;
    const usados = new Map();
    return listaComparacion.filter(item => {
        const mw = _tiristoresNumero(item?.mw);
        if (!Number.isFinite(mw)) return true;
        const key = mw.toFixed(3);
        const max = disponibles.get(key) || 0;
        if (!max) return Number.isFinite(maxActual) && mw > maxActual + 0.001;
        const actual = usados.get(key) || 0;
        if (actual >= max) return false;
        usados.set(key, actual + 1);
        return true;
    });
}

function _tiristoresTieneDatos(item) {
    if (!item) return false;
    if (String(item.hora || '').trim() || String(item.mw || '').trim()) return true;
    return TIRISTOR_PUNTOS_FICHA.some(p => item.entrada?.[p] || item.salida?.[p] || item.frente?.[p]);
}

function _tiristoresMax(item, tipo) {
    const values = TIRISTOR_PUNTOS_FICHA
        .map(p => _tiristoresNumero(item?.[tipo]?.[p]))
        .filter(v => Number.isFinite(v));
    return values.length ? Math.max(...values) : null;
}

function _tiristoresMaxDetalle(mediciones = []) {
    let best = null;
    mediciones.forEach((item, index) => {
        ['entrada', 'salida'].forEach(tipo => {
            TIRISTOR_PUNTOS_FICHA.forEach(punto => {
                const value = _tiristoresNumero(item?.[tipo]?.[punto]);
                if (!Number.isFinite(value)) return;
                if (!best || value > best.value) {
                    best = { id: item?.id || '', value, tipo, punto, index, hora: item?.hora || '', nota: item?.nota || '', mw: item?.mw || '' };
                }
            });
        });
    });
    return best;
}

function _tiristoresModuloDePunto(punto) {
    const modulo = String(punto || '').trim().charAt(0).toLowerCase();
    return TIRISTOR_MODULOS_FICHA.includes(modulo) ? modulo : 'x';
}

function _tiristoresTipoLabel(tipo) {
    return tipo === 'entrada' ? 'Entrada' : tipo === 'salida' ? 'Salida' : 'Frente';
}

function _tiristoresParametroTexto(item, key, unidad) {
    const value = String(item?.parametros?.[key] || '').trim();
    return value ? `${value}${unidad}` : '-';
}

function _tiristoresFrenteResumen(item) {
    const partes = TIRISTOR_PUNTOS_FICHA
        .map(p => {
            const value = String(item?.frente?.[p] || '').trim();
            return value ? `${TIRISTOR_LABELS_FICHA[p]} ${value} C` : '';
        })
        .filter(Boolean);
    return partes.length ? partes.join(' / ') : '-';
}

function _tiristoresUnidadesDisponibles(unidadActual = '') {
    const store = _tiristoresStoreLeer();
    const unidades = new Set(['U3', 'U5']);
    Object.keys(store || {}).forEach(key => {
        if (/^U[35]$/.test(key)) unidades.add(key);
    });
    Object.keys(TIRISTORES_BASE_PDF || {}).forEach(key => unidades.add(key));
    return [...unidades].filter(u => u && u !== unidadActual).sort((a, b) => a.localeCompare(b, 'es', { numeric: true }));
}

function _tiristoresLabelMedicion(item, index) {
    const hora = String(item?.hora || '').trim();
    const nota = String(item?.nota || '').trim();
    return [hora, nota].filter(Boolean).join(' ') || `#${index + 1}`;
}

function _tiristoresLabelCarga(item, index, mostrarHora = true) {
    const mw = String(item?.mw || '').trim();
    const hora = String(item?.hora || '').trim();
    const carga = mw ? `${mw.replace('.', ',')} MW` : `#${index + 1}`;
    return mostrarHora && hora ? [carga, hora] : carga;
}

function _tiristoresPuntoGrafico(item, valor) {
    const xVisual = _tiristoresNumero(item?._chartX);
    const x = Number.isFinite(xVisual) ? xVisual : _tiristoresNumero(item?.mw);
    const y = _tiristoresNumero(valor);
    if (!Number.isFinite(x) || !Number.isFinite(y)) return null;
    return {
        x,
        y,
        id: item?.id || '',
        hora: item?.hora || '',
        mw: item?.mw || '',
        nota: item?.nota || '',
        parametros: item?.parametros || {}
    };
}

function _tiristoresSepararCargasRepetidas(lista = [], offsetUnidad = 0) {
    const grupos = new Map();
    lista.forEach((item, index) => {
        const mw = _tiristoresNumero(item?.mw);
        const key = Number.isFinite(mw) ? mw.toFixed(3) : `sin-${item?.id || index}`;
        grupos.set(key, (grupos.get(key) || 0) + 1);
    });
    const vistos = new Map();
    return lista.map(item => {
        const mw = _tiristoresNumero(item?.mw);
        if (!Number.isFinite(mw)) return { ...item, _chartX: offsetUnidad };
        const key = mw.toFixed(3);
        const total = grupos.get(key) || 1;
        const pos = vistos.get(key) || 0;
        vistos.set(key, pos + 1);
        const step = total <= 1 ? 0 : total <= 2 ? 2.4 : total <= 4 ? 1.9 : 1.45;
        const offset = (pos - (total - 1) / 2) * step + offsetUnidad;
        return { ...item, _chartX: Math.max(0, mw + offset) };
    });
}

function _tiristoresPrepararSecuencia(lista = [], offsetUnidad = 0) {
    return lista.map((item, index) => ({
        ...item,
        _chartX: index + 1 + offsetUnidad,
        _chartIndex: index
    }));
}

function _tiristoresPrepararComparacionEnSlots(listaComparacion = [], listaActualPreparada = []) {
    const slotsPorMw = new Map();
    const cargasActuales = [];
    let siguienteX = 1;
    listaActualPreparada.forEach(item => {
        const mw = _tiristoresNumero(item?.mw);
        if (!Number.isFinite(mw)) return;
        cargasActuales.push(mw);
        siguienteX = Math.max(siguienteX, Math.ceil(Number(item._chartX) || 0) + 1);
        const key = mw.toFixed(3);
        if (!slotsPorMw.has(key)) slotsPorMw.set(key, []);
        slotsPorMw.get(key).push(item._chartX);
    });
    const maxActual = cargasActuales.length ? Math.max(...cargasActuales) : null;
    const usados = new Map();
    return listaComparacion
        .map(item => {
            const mw = _tiristoresNumero(item?.mw);
            if (!Number.isFinite(mw)) return null;
            const key = mw.toFixed(3);
            const slots = slotsPorMw.get(key) || [];
            const index = usados.get(key) || 0;
            if (!slots[index]) {
                if (Number.isFinite(maxActual) && mw > maxActual + 0.001) {
                    return { ...item, _chartX: siguienteX++, _chartIndex: index };
                }
                return null;
            }
            usados.set(key, index + 1);
            return { ...item, _chartX: slots[index], _chartIndex: index };
        })
        .filter(Boolean);
}

function _tiristoresJs(value) {
    return String(value ?? '').replace(/\\/g, '\\\\').replace(/'/g, "\\'");
}

function _tiristoresInputGrid(data = {}) {
    const input = (tipo, punto) => {
        const cls = tipo === 'entrada' ? 'tir-in' : tipo === 'salida' ? 'tir-out' : 'tir-front';
        return `<input type="number" class="form-control ${cls}-${punto}" step="0.1" min="-50" value="${escapeHtml(data?.[tipo]?.[punto] || '')}" placeholder="${TIRISTOR_LABELS_FICHA[punto]}" style="font-size:0.82rem; padding:0.42rem 0.5rem;">`;
    };
    const fila = tipo => `<div style="display:grid; grid-template-columns:78px repeat(6, minmax(58px, 1fr)); gap:0.35rem; align-items:center;">
        <strong style="font-size:0.78rem; color:#475569;">${tipo === 'entrada' ? 'Entrada' : tipo === 'salida' ? 'Salida' : 'Frente'}</strong>
        ${TIRISTOR_PUNTOS_FICHA.map(p => input(tipo, p)).join('')}
    </div>`;
    return `<div style="display:grid; gap:0.45rem;">
        <div style="display:grid; grid-template-columns:78px repeat(6, minmax(58px, 1fr)); gap:0.35rem; align-items:center; color:#64748b; font-size:0.72rem; font-weight:800; text-align:center;">
            <span></span>${TIRISTOR_PUNTOS_FICHA.map(p => `<span>${TIRISTOR_LABELS_FICHA[p]}</span>`).join('')}
        </div>
        ${fila('entrada')}
        ${fila('salida')}
        ${fila('frente')}
    </div>`;
}

function renderFichaTiristoresPanel(equipo) {
    const cont = document.getElementById('ficha-tiristores');
    if (!cont) return;
    const unidad = _tiristoresUnidadEquipo(equipo);
    window._planifyFichaTiristores = { unidad, mediciones: [] };
    if (!unidad) {
        cont.innerHTML = `<div class="planify-ficha-card-head"><div><h3>Tiristores</h3><span>Modulo disponible para Excitatriz U3 y U5.</span></div></div>${emptyFichaState('Sin modulo de tiristores', 'Abre la ficha de la excitatriz U3 o U5 para registrar entrada, salida, hora y MW.')}`;
        return;
    }

    const mediciones = _tiristoresLeerUnidad(unidad);
    window._planifyFichaTiristores = { unidad, mediciones };
    const latest = mediciones[mediciones.length - 1] || null;
    const maxSalida = mediciones.map(m => _tiristoresMax(m, 'salida')).filter(v => v !== null);
    const maxEntrada = mediciones.map(m => _tiristoresMax(m, 'entrada')).filter(v => v !== null);
    const maxTemp = Math.max(...[...maxSalida, ...maxEntrada, 0]);
    const maxDetalle = _tiristoresMaxDetalle(mediciones);
    window._planifyTiristorMaxDetalle = maxDetalle;
    const maxMw = Math.max(...mediciones.map(m => _tiristoresNumero(m.mw) || 0), 0);
    const promedio = values => values.length ? values.reduce((a, b) => a + b, 0) / values.length : null;
    const allTemps = mediciones.flatMap(m => TIRISTOR_PUNTOS_FICHA.flatMap(p => [
        _tiristoresNumero(m.entrada?.[p]),
        _tiristoresNumero(m.salida?.[p])
    ])).filter(v => Number.isFinite(v));
    const maxTempMeta = maxDetalle
        ? `Modulo ${TIRISTOR_MODULO_LABELS_FICHA[_tiristoresModuloDePunto(maxDetalle.punto)]} / ${_tiristoresTipoLabel(maxDetalle.tipo)}${maxDetalle.hora ? ` / ${escapeHtml(maxDetalle.hora)}` : ''}`
        : 'Mayor valor entre entrada y salida';
    const maxTempCard = maxDetalle ? `
            <article class="planify-ficha-mini ${getEstadoCondicionFicha('termografia', maxTemp).tone}" role="button" tabindex="0"
                onclick="window.irMaximaTempTiristores()"
                onkeydown="if(event.key==='Enter'||event.key===' '){event.preventDefault();window.irMaximaTempTiristores();}"
                title="Ver modulo ${escapeHtml(TIRISTOR_MODULO_LABELS_FICHA[_tiristoresModuloDePunto(maxDetalle.punto)])} en el grafico"
                style="cursor:pointer; border-color:#fecaca; box-shadow:0 10px 24px rgba(220,38,38,0.08);">
                <div class="planify-ficha-mini-label">Maximo temp.</div>
                <div class="planify-ficha-mini-value">${numeroFicha(maxTemp, 1)} C</div>
                <div class="planify-ficha-mini-meta">${maxTempMeta}</div>
            </article>` : crearTarjetaMiniFicha({ label: 'Maximo temp.', value: `${numeroFicha(maxTemp, 1)} C`, meta: 'Mayor valor entre entrada y salida', tone: getEstadoCondicionFicha('termografia', maxTemp).tone });
    const resumen = mediciones.length ? `
        <div class="planify-ficha-subgrid" style="margin-bottom:0.9rem;">
            ${crearTarjetaMiniFicha({ label: 'Mediciones', value: numeroFicha(mediciones.length), meta: latest?.hora ? `Ultima hora: ${escapeHtml(latest.hora)}` : 'Sin hora registrada' })}
            ${maxTempCard}
            ${crearTarjetaMiniFicha({ label: 'Promedio', value: allTemps.length ? `${numeroFicha(promedio(allTemps), 1)} C` : 'Sin dato', meta: `${numeroFicha(allTemps.length)} punto(s) con temperatura` })}
            ${crearTarjetaMiniFicha({ label: 'Maximo MW', value: maxMw ? `${numeroFicha(maxMw, 0)} MW` : 'Sin dato', meta: 'Carga asociada a las mediciones' })}
        </div>` : '';
    const moduloActivo = TIRISTOR_MODULOS_FICHA.includes(window._planifyTiristorModuloActivo)
        ? window._planifyTiristorModuloActivo
        : _tiristoresModuloDePunto(window._planifyTiristorPuntoActivo);
    window._planifyTiristorModuloActivo = moduloActivo;
    const unidadesComparables = _tiristoresUnidadesDisponibles(unidad);
    const compararActivo = unidadesComparables.includes(window._planifyTiristorCompararUnidad)
        ? window._planifyTiristorCompararUnidad
        : '';
    window._planifyTiristorCompararUnidad = compararActivo;
    const modoActivo = window._planifyTiristorModo === 'mw-real' ? 'mw-real' : 'secuencia';
    window._planifyTiristorModo = modoActivo;
    const charts = mediciones.length ? `
        <section style="border:1px solid #e5e7eb; border-radius:14px; background:#fff; padding:0.9rem; margin-top:0.9rem;">
            <div style="display:flex; justify-content:space-between; align-items:flex-start; gap:0.8rem; flex-wrap:wrap; margin-bottom:0.75rem;">
                <div>
                    <div style="font-size:0.95rem; color:#0f172a; font-weight:900;"><i class="fa-solid fa-chart-line" style="color:#7c3aed;"></i> Modulo <span id="tir-modulo-titulo">${TIRISTOR_MODULO_LABELS_FICHA[moduloActivo]}</span></div>
                    <div id="tir-comparador-subtitulo" style="font-size:0.78rem; color:#64748b; margin-top:0.18rem;">Entrada y salidas del modulo en Orden Medición.</div>
                </div>
                <div style="display:flex; align-items:center; gap:0.5rem; flex-wrap:wrap; justify-content:flex-end;">
                    <label style="display:flex; align-items:center; gap:0.35rem; font-size:0.78rem; color:#64748b; font-weight:800;">
                        Modo
                        <select id="tir-modo-select" class="form-control" onchange="window.seleccionarModoTiristores(this.value)" style="width:auto; min-width:150px; font-size:0.82rem; padding:0.38rem 0.55rem;">
                            <option value="secuencia" ${modoActivo === 'secuencia' ? 'selected' : ''}>Orden Medición</option>
                            <option value="mw-real" ${modoActivo === 'mw-real' ? 'selected' : ''}>Tendencia MW</option>
                        </select>
                    </label>
                    <div id="tir-modulo-botones" style="display:flex; gap:0.35rem; flex-wrap:wrap;">
                        ${TIRISTOR_MODULOS_FICHA.map(m => {
                            const active = m === moduloActivo;
                            return `<button type="button" data-tir-modulo="${m}" onclick="window.seleccionarModuloTiristores('${m}')"
                                style="min-width:42px; border:1px solid ${active ? '#7c3aed' : '#e5e7eb'}; background:${active ? '#f5f3ff' : '#fff'}; color:${active ? '#6d28d9' : '#475569'}; border-radius:999px; padding:0.38rem 0.65rem; font-size:0.78rem; font-weight:900; cursor:pointer;">
                                ${TIRISTOR_MODULO_LABELS_FICHA[m]}
                            </button>`;
                        }).join('')}
                    </div>
                    <select id="tir-modulo-select" class="form-control" onchange="window.seleccionarModuloTiristores(this.value)" style="width:auto; min-width:90px; font-size:0.82rem; padding:0.38rem 0.55rem;">
                        ${TIRISTOR_MODULOS_FICHA.map(m => `<option value="${m}" ${m === moduloActivo ? 'selected' : ''}>Modulo ${TIRISTOR_MODULO_LABELS_FICHA[m]}</option>`).join('')}
                    </select>
                    <label style="display:flex; align-items:center; gap:0.35rem; font-size:0.78rem; color:#64748b; font-weight:800;">
                        Comparar
                        <select id="tir-comparar-select" class="form-control" onchange="window.seleccionarComparadorTiristores(this.value)" style="width:auto; min-width:132px; font-size:0.82rem; padding:0.38rem 0.55rem;">
                            <option value="">Sin comparacion</option>
                            ${unidadesComparables.map(u => `<option value="${u}" ${u === compararActivo ? 'selected' : ''}>con ${u}</option>`).join('')}
                        </select>
                    </label>
                </div>
            </div>
            <div style="height:clamp(520px, 68vh, 680px); min-height:520px;"><canvas id="tir-chart-principal"></canvas></div>
            <div id="tir-comparador-estado" style="font-size:0.78rem; color:#64748b; margin-top:0.55rem;"></div>
        </section>` : emptyFichaState('Sin mediciones de tiristores', 'Agrega la hora de medicion, MW y temperaturas de entrada/salida para graficar cada punto.');
    const filas = mediciones.length ? `<div style="overflow-x:auto; margin-top:0.9rem;">
        <table style="width:100%; border-collapse:collapse; font-size:0.82rem; min-width:980px;">
            <thead><tr style="background:#f8fafc; color:#475569;">
                <th style="text-align:left; padding:0.5rem;">Hora</th>
                <th style="text-align:center; padding:0.5rem;">MW</th>
                <th style="text-align:center; padding:0.5rem;">V campo</th>
                <th style="text-align:center; padding:0.5rem;">I campo</th>
                <th style="text-align:center; padding:0.5rem;">Max entrada</th>
                <th style="text-align:center; padding:0.5rem;">Max salida</th>
                <th style="text-align:left; padding:0.5rem;">Frente</th>
                <th style="text-align:left; padding:0.5rem;">Nota</th>
                <th style="text-align:right; padding:0.5rem;">Acciones</th>
            </tr></thead>
            <tbody>${mediciones.map(m => `<tr style="border-top:1px solid #e5e7eb;">
                <td style="padding:0.45rem 0.5rem; font-weight:800; color:#0f172a;">${escapeHtml(m.hora || '-')}</td>
                <td style="padding:0.45rem 0.5rem; text-align:center;">${escapeHtml(m.mw || '-')}</td>
                <td style="padding:0.45rem 0.5rem; text-align:center;">${escapeHtml(_tiristoresParametroTexto(m, 'vcampo', 'V'))}</td>
                <td style="padding:0.45rem 0.5rem; text-align:center;">${escapeHtml(_tiristoresParametroTexto(m, 'icampo', 'A'))}</td>
                <td style="padding:0.45rem 0.5rem; text-align:center;">${_tiristoresMax(m, 'entrada') !== null ? `${numeroFicha(_tiristoresMax(m, 'entrada'), 1)} C` : '-'}</td>
                <td style="padding:0.45rem 0.5rem; text-align:center;">${_tiristoresMax(m, 'salida') !== null ? `${numeroFicha(_tiristoresMax(m, 'salida'), 1)} C` : '-'}</td>
                <td style="padding:0.45rem 0.5rem;">${escapeHtml(_tiristoresFrenteResumen(m))}</td>
                <td style="padding:0.45rem 0.5rem;">${escapeHtml(m.nota || '')}</td>
                <td style="padding:0.45rem 0.5rem; text-align:right; white-space:nowrap;">
                    <button onclick="window.abrirModalTiristores('${unidad}','${_tiristoresJs(m.id)}')" title="Editar" style="background:none; border:none; color:#7c3aed; cursor:pointer; padding:0.25rem;"><i class="fa-solid fa-pen"></i></button>
                    <button onclick="window.eliminarMedicionTiristores('${unidad}','${_tiristoresJs(m.id)}')" title="Eliminar" style="background:none; border:none; color:#94a3b8; cursor:pointer; padding:0.25rem;" onmouseover="this.style.color='#ef4444'" onmouseout="this.style.color='#94a3b8'"><i class="fa-solid fa-trash"></i></button>
                </td>
            </tr>`).join('')}</tbody>
        </table>
    </div>` : '';

    cont.innerHTML = `
        <div class="planify-ficha-card-head">
            <div>
                <h3><i class="fa-solid fa-microchip" style="color:#7c3aed;"></i> Tiristores ${unidad}</h3>
                <span>Tendencias por punto con hora de medicion, sin fecha visible.</span>
            </div>
            <div style="display:flex; gap:0.5rem; flex-wrap:wrap;">
                <button onclick="window.compartirVistaTiristores('${unidad}')" class="btn btn-outline planify-ficha-action-btn" style="color:#0f766e; border-color:#99f6e4;" title="Copiar link publico de solo lectura con la vista actual">
                    <i class="fa-solid fa-share-nodes"></i> Compartir
                </button>
                <button onclick="window.abrirModalTiristores('${unidad}')" class="btn btn-outline planify-ficha-action-btn" style="color:#7c3aed; border-color:#ddd6fe;">
                    <i class="fa-solid fa-plus"></i> Agregar medicion
                </button>
            </div>
        </div>
        ${resumen}
        ${charts}
        ${filas}
    `;
}

window.abrirModalTiristores = function(unidad, id = '') {
    const lista = _tiristoresLeerUnidad(unidad);
    const actual = id ? lista.find(item => String(item.id) === String(id)) : null;
    document.getElementById('modal-tiristores')?.remove();
    const overlay = document.createElement('div');
    overlay.id = 'modal-tiristores';
    overlay.dataset.unidad = unidad;
    overlay.dataset.id = actual?.id || '';
    overlay.style.cssText = 'position:fixed; inset:0; background:rgba(15,23,42,0.55); z-index:12000; display:flex; align-items:flex-start; justify-content:center; padding:2rem 1rem; overflow:auto;';
    overlay.innerHTML = `
        <div style="background:#fff; border-radius:16px; max-width:880px; width:100%; box-shadow:0 24px 60px rgba(0,0,0,0.3);">
            <div style="display:flex; justify-content:space-between; align-items:center; gap:1rem; padding:1rem 1.2rem; border-bottom:1px solid #eef2f7;">
                <strong style="font-size:1rem; color:#0f172a;"><i class="fa-solid fa-microchip" style="color:#7c3aed;"></i> ${actual ? 'Editar' : 'Agregar'} medicion Tiristores ${unidad}</strong>
                <button onclick="document.getElementById('modal-tiristores').remove()" style="background:none; border:none; font-size:1.4rem; line-height:1; cursor:pointer; color:#94a3b8;">&times;</button>
            </div>
            <div style="padding:1rem 1.2rem; display:grid; gap:0.85rem;">
                <div style="display:grid; grid-template-columns:repeat(auto-fit,minmax(140px,1fr)); gap:0.7rem;">
                    <label style="display:grid; gap:0.25rem; font-size:0.78rem; color:#475569; font-weight:800;">Hora medicion
                        <input type="time" id="tir-hora" class="form-control" value="${escapeHtml(actual?.hora || '')}">
                    </label>
                    <label style="display:grid; gap:0.25rem; font-size:0.78rem; color:#475569; font-weight:800;">Megawatts
                        <input type="number" id="tir-mw" class="form-control" step="0.1" min="0" value="${escapeHtml(actual?.mw || '')}" placeholder="Ej: 67">
                    </label>
                    <label style="display:grid; gap:0.25rem; font-size:0.78rem; color:#475569; font-weight:800;">V campo
                        <input type="number" id="tir-vcampo" class="form-control" step="0.1" min="0" value="${escapeHtml(actual?.parametros?.vcampo || '')}" placeholder="Ej: 64">
                    </label>
                    <label style="display:grid; gap:0.25rem; font-size:0.78rem; color:#475569; font-weight:800;">I campo
                        <input type="number" id="tir-icampo" class="form-control" step="0.1" min="0" value="${escapeHtml(actual?.parametros?.icampo || '')}" placeholder="Ej: 557">
                    </label>
                    <label style="display:grid; gap:0.25rem; font-size:0.78rem; color:#475569; font-weight:800;">Medicion
                        <input id="tir-nota" class="form-control" value="${escapeHtml(actual?.nota || '')}" placeholder="Ej: 1, 2 o post intervencion">
                    </label>
                </div>
                <div style="border:1px solid #e5e7eb; border-radius:12px; padding:0.8rem; background:#f8fafc; overflow-x:auto;">
                    ${_tiristoresInputGrid(actual || {})}
                </div>
            </div>
            <div style="display:flex; gap:0.6rem; justify-content:flex-end; padding:1rem 1.2rem; border-top:1px solid #eef2f7;">
                <button onclick="document.getElementById('modal-tiristores').remove()" style="background:#fff; border:1px solid #e5e7eb; border-radius:9px; padding:0.6rem 1.1rem; font-weight:700; cursor:pointer; color:#475569;">Cancelar</button>
                <button onclick="window.guardarMedicionTiristores()" style="background:linear-gradient(135deg,#7c3aed,#a855f7); color:#fff; border:none; border-radius:9px; padding:0.6rem 1.3rem; font-weight:800; cursor:pointer;"><i class="fa-solid fa-floppy-disk"></i> Guardar</button>
            </div>
        </div>`;
    document.body.appendChild(overlay);
};

window.guardarMedicionTiristores = function() {
    const modal = document.getElementById('modal-tiristores');
    if (!modal) return;
    const unidad = modal.dataset.unidad || '';
    const id = modal.dataset.id || crypto.randomUUID();
    const entrada = {}, salida = {}, frente = {};
    TIRISTOR_PUNTOS_FICHA.forEach(p => {
        entrada[p] = modal.querySelector(`.tir-in-${p}`)?.value.trim() || '';
        salida[p] = modal.querySelector(`.tir-out-${p}`)?.value.trim() || '';
        frente[p] = modal.querySelector(`.tir-front-${p}`)?.value.trim() || '';
    });
    const item = {
        id,
        unidad,
        hora: modal.querySelector('#tir-hora')?.value || '',
        mw: modal.querySelector('#tir-mw')?.value.trim() || '',
        nota: modal.querySelector('#tir-nota')?.value.trim() || '',
        entrada,
        salida,
        frente,
        parametros: {
            vcampo: modal.querySelector('#tir-vcampo')?.value.trim() || '',
            icampo: modal.querySelector('#tir-icampo')?.value.trim() || ''
        },
        created_at: new Date().toISOString()
    };
    if (!_tiristoresTieneDatos(item)) {
        alert('Ingresa al menos hora, MW o una temperatura.');
        return;
    }
    const lista = _tiristoresLeerUnidad(unidad).filter(m => String(m.id) !== String(id));
    lista.push(item);
    _tiristoresGuardarUnidad(unidad, lista);
    modal.remove();
    const equipo = window._planifyFichaTiristoresEquipo;
    if (equipo) {
        renderFichaTiristoresPanel(equipo);
        setTimeout(() => initFichaTiristoresCharts(), 30);
    }
};

window.eliminarMedicionTiristores = function(unidad, id) {
    if (!confirm('Eliminar esta medicion de tiristores?')) return;
    _tiristoresGuardarUnidad(unidad, _tiristoresLeerUnidad(unidad).filter(item => String(item.id) !== String(id)));
    const equipo = window._planifyFichaTiristoresEquipo;
    if (equipo) {
        renderFichaTiristoresPanel(equipo);
        setTimeout(() => initFichaTiristoresCharts(), 30);
    }
};

window.seleccionarModuloTiristores = function(modulo) {
    if (!TIRISTOR_MODULOS_FICHA.includes(modulo)) return;
    window._planifyTiristorModuloActivo = modulo;
    window._planifyTiristorPuntoActivo = `${modulo}1`;
    document.getElementById('tir-modulo-titulo')?.replaceChildren(document.createTextNode(TIRISTOR_MODULO_LABELS_FICHA[modulo]));
    const select = document.getElementById('tir-modulo-select');
    if (select) select.value = modulo;
    document.querySelectorAll('[data-tir-modulo]').forEach(btn => {
        const active = btn.dataset.tirModulo === modulo;
        btn.style.borderColor = active ? '#7c3aed' : '#e5e7eb';
        btn.style.background = active ? '#f5f3ff' : '#fff';
        btn.style.color = active ? '#6d28d9' : '#475569';
    });
    initFichaTiristoresCharts();
};

window.seleccionarPuntoTiristores = function(punto) {
    window.seleccionarModuloTiristores(_tiristoresModuloDePunto(punto));
};

window.seleccionarComparadorTiristores = function(unidad) {
    const actual = window._planifyFichaTiristores?.unidad || '';
    const opciones = _tiristoresUnidadesDisponibles(actual);
    window._planifyTiristorCompararUnidad = opciones.includes(unidad) ? unidad : '';
    const select = document.getElementById('tir-comparar-select');
    if (select) select.value = window._planifyTiristorCompararUnidad;
    initFichaTiristoresCharts();
};

window.seleccionarOrdenTiristores = function(orden) {
    window.seleccionarModoTiristores(orden === 'mw' ? 'mw-real' : 'secuencia');
};

window.seleccionarModoTiristores = function(modo) {
    window._planifyTiristorModo = modo === 'mw-real' ? 'mw-real' : 'secuencia';
    const select = document.getElementById('tir-modo-select');
    if (select) select.value = window._planifyTiristorModo;
    initFichaTiristoresCharts();
};

// Link publico de solo lectura (GitHub Pages). Los datos van embebidos en el
// hash del link, asi funciona aunque la app corra solo en este equipo.
const TIRISTORES_PUBLIC_URL = 'https://benja1808.github.io/planify-app/tiristores.html';

window.compartirVistaTiristores = async function(unidad) {
    const unidades = {};
    const disponibles = new Set([unidad, ..._tiristoresUnidadesDisponibles('')]);
    disponibles.forEach(u => {
        if (!u) return;
        const lista = _tiristoresLeerUnidad(u);
        if (lista.length) unidades[u] = lista;
    });
    const payload = {
        v: 1,
        generado: new Date().toISOString(),
        vista: {
            unidad,
            modulo: TIRISTOR_MODULOS_FICHA.includes(window._planifyTiristorModuloActivo) ? window._planifyTiristorModuloActivo : 'x',
            modo: window._planifyTiristorModo === 'mw-real' ? 'mw-real' : 'secuencia',
            comparar: window._planifyTiristorCompararUnidad || ''
        },
        unidades
    };
    const json = JSON.stringify(payload);
    // LZ-String deja el link en ~25% del tamano; sin la lib cae a base64 plano.
    const hash = window.LZString
        ? `d=${window.LZString.compressToEncodedURIComponent(json)}`
        : `j=${encodeURIComponent(btoa(unescape(encodeURIComponent(json))))}`;
    const url = `${TIRISTORES_PUBLIC_URL}#${hash}`;
    try {
        await navigator.clipboard.writeText(url);
        mostrarToastNotificacion('Link copiado', 'Vista de tiristores de solo lectura, incluye tus mediciones actuales.', { type: 'success' });
    } catch (e) {
        window.prompt('Copia el link para compartir:', url);
    }
};

window.irMaximaTempTiristores = function() {
    const detalle = window._planifyTiristorMaxDetalle;
    if (!detalle?.punto) return;
    window.seleccionarModuloTiristores(_tiristoresModuloDePunto(detalle.punto));
    setTimeout(() => {
        const canvas = document.getElementById('tir-chart-principal');
        const section = canvas?.closest('section');
        section?.scrollIntoView({ behavior: 'smooth', block: 'center' });
        if (section) {
            section.style.boxShadow = '0 0 0 3px rgba(124,58,237,0.18)';
            setTimeout(() => { section.style.boxShadow = ''; }, 1400);
        }
        const chart = activeCharts.find(item => item?.canvas?.id === 'tir-chart-principal');
        let datasetIndex = 0;
        if (detalle.tipo === 'salida') datasetIndex = String(detalle.punto || '').endsWith('2') ? 2 : 1;
        if (!chart || datasetIndex < 0) return;
        const dataset = chart.data?.datasets?.[datasetIndex];
        const index = dataset?.data?.findIndex(point => String(point?.id || '') === String(detalle.id || '')) ?? -1;
        if (index < 0) return;
        const point = dataset.data[index] || {};
        const x = chart.scales?.x?.getPixelForValue(point.x) || 0;
        const y = chart.scales?.y?.getPixelForValue(point.y) || 0;
        chart.setActiveElements([{ datasetIndex, index }]);
        chart.tooltip?.setActiveElements([{ datasetIndex, index }], { x, y });
        chart.update();
    }, 80);
};

function renderListasFicha(equipo, medicionesEquipo, medicionesGrupo, tareasRelacionadas, fuenteMediciones) {
    // 1º técnico desde la ejecución de ruta (las mediciones de ruta no guardan
    // técnico en la tabla, lo heredan de la ruta asignada); 2º desde tareas.
    medicionesEquipo = completarTecnicosBombasEmergenciaFicha(medicionesEquipo, equipo);
    medicionesEquipo = enriquecerMedicionesConRutaFicha(medicionesEquipo, equipo);
    medicionesGrupo = enriquecerMedicionesConRutaFicha(medicionesGrupo, equipo);
    medicionesEquipo = enriquecerMedicionesConTecnicosFicha(medicionesEquipo, tareasRelacionadas);
    medicionesGrupo = enriquecerMedicionesConTecnicosFicha(medicionesGrupo, tareasRelacionadas);
    const vibs = medicionesEquipo.filter(m => m.tipo === 'vibracion').sort((a, b) => new Date(b.fecha) - new Date(a.fecha));
    const termos = medicionesEquipo.filter(m => m.tipo === 'termografia').sort((a, b) => new Date(b.fecha) - new Date(a.fecha));
    const lubs = medicionesEquipo.filter(m => m.tipo === 'lubricacion').sort((a, b) => new Date(b.fecha) - new Date(a.fecha));
    const siblingEquipos = estado.equipos.filter(item => item.activo === equipo.activo && item.ubicacion === equipo.ubicacion);
    const siblingIds = new Set(siblingEquipos.map(item => String(item.id)));
    const vibSummary = obtenerResumenMedicionesFicha(medicionesEquipo, 'vibracion');
    const termoSummary = obtenerResumenMedicionesFicha(medicionesEquipo, 'termografia');
    const overallStatus = consolidarEstadoFicha([vibSummary.count ? vibSummary.status : null, termoSummary.count ? termoSummary.status : null].filter(Boolean));
    const ultimaActividad = tareasRelacionadas[0] || null;
    const pulsoActivo = getPulsoActivoFicha(equipo, { vibracion: vibSummary, termografia: termoSummary }, tareasRelacionadas);
    const brechaVib = getBrechaUmbralFicha('vibracion', vibSummary);
    const brechaTermo = getBrechaUmbralFicha('termografia', termoSummary);
    const comparativaVib = getComparativaGrupoFicha(equipo, siblingEquipos, medicionesGrupo, 'vibracion');
    const comparativaTermo = getComparativaGrupoFicha(equipo, siblingEquipos, medicionesGrupo, 'termografia');
    const comparativaTone = priorizarToneFicha(comparativaVib.tone, comparativaTermo.tone);
    const comparativaValue = comparativaVib.value !== 'Sin dato'
        ? `Vib ${comparativaVib.value}`
        : (comparativaTermo.value !== 'Sin dato' ? `Temp ${comparativaTermo.value}` : numeroFicha(siblingEquipos.length));
    const comparativaMeta = [
        comparativaVib.value !== 'Sin dato' ? `Vibracion: ${comparativaVib.meta}` : '',
        comparativaTermo.value !== 'Sin dato' ? `Termografia: ${comparativaTermo.meta}` : ''
    ].filter(Boolean).join(' / ') || (siblingEquipos.length > 1
        ? 'Hay componentes hermanos, pero aun no existe una base comparable.'
        : 'Activo sin componentes comparables en esta unidad.');
    const totalLecturas = vibSummary.count + termoSummary.count + lubs.length;
    const critStyles = {
        A: { text: 'Criticidad A', bg: '#fef2f2', color: '#b91c1c', border: '#fecaca' },
        B: { text: 'Criticidad B', bg: '#fff7ed', color: '#b45309', border: '#fdba74' },
        C: { text: 'Criticidad C', bg: '#ecfdf5', color: '#047857', border: '#a7f3d0' }
    };
    const crit = critStyles[equipo.criticidad] || { text: equipo.criticidad || 'Sin criticidad', bg: '#f8fafc', color: '#475569', border: '#cbd5e1' };
    const badgeCrit = document.getElementById('ficha-equipo-criticidad');
    badgeCrit.className = 'badge';
    badgeCrit.textContent = crit.text;
    badgeCrit.style.background = crit.bg;
    badgeCrit.style.color = crit.color;
    badgeCrit.style.border = `1px solid ${crit.border}`;
    document.getElementById('ficha-equipo-nombre').textContent = `${equipo.activo}${equipo.componente ? ' · ' + equipo.componente : ''}`;
    document.getElementById('ficha-equipo-ubicacion').textContent = equipo.ubicacion || 'Sin ubicación';
    document.getElementById('ficha-equipo-kks').textContent = equipo.kks || 'N/A';
    document.getElementById('ficha-equipo-breadcrumb').innerHTML = `<span>Control</span><i class="fa-solid fa-angle-right"></i><span>${equipo.ubicacion || 'Sin unidad'}</span><i class="fa-solid fa-angle-right"></i><strong>${equipo.activo}</strong>${equipo.componente ? `<i class="fa-solid fa-angle-right"></i><span>${equipo.componente}</span>` : ''}`;
    document.getElementById('ficha-equipo-extra').innerHTML = [
        equipo.denominacion_ut ? `<span><i class="fa-solid fa-tag"></i> ${equipo.denominacion_ut}</span>` : '',
        equipo.frecuencia_nueva ? `<span><i class="fa-solid fa-clock-rotate-left"></i> Frecuencia: ${equipo.frecuencia_nueva} días</span>` : '',
        equipo.ruta ? `<span><i class="fa-solid fa-route"></i> ${equipo.ruta}</span>` : '',
        equipo.ubicacion_tecnica ? `<span><i class="fa-solid fa-diagram-project"></i> ${equipo.ubicacion_tecnica}</span>` : ''
    ].filter(Boolean).join('');
    const sourceEl = document.getElementById('ficha-equipo-source');
    const sourceMap = {
        online: '<i class="fa-solid fa-cloud-arrow-down"></i> Datos online',
        estado: '<i class="fa-solid fa-bolt"></i> Cache de sesión',
        local: '<i class="fa-solid fa-hard-drive"></i> Cache local',
        none: '<i class="fa-solid fa-circle-info"></i> Sin mediciones'
    };
    sourceEl.innerHTML = sourceMap[fuenteMediciones] || sourceMap.none;
    sourceEl.style.display = 'inline-flex';
    document.getElementById('ficha-equipo-actions').innerHTML = `
        <button class="btn btn-outline planify-ficha-action-btn" onclick="window.irAHistorialDeEquipo('${equipo.id}')"><i class="fa-solid fa-clock-rotate-left"></i> Historial</button>
        <button class="btn btn-outline planify-ficha-action-btn" onclick="window.irAControlConBusqueda('${equipo.id}')"><i class="fa-solid fa-magnifying-glass"></i> Buscar</button>
        <button class="btn btn-outline planify-ficha-action-btn" onclick="window.abrirVistaUnidad('${String(equipo.ubicacion || '').replace(/'/g, "\\'")}')"><i class="fa-solid fa-location-dot"></i> Unidad</button>
    `;
    document.getElementById('ficha-equipo-overview').innerHTML = [
        crearTarjetaResumenFicha({ label: 'Estado actual', value: overallStatus.label, meta: vibSummary.count || termoSummary.count ? `Vibración ${vibSummary.count ? vibSummary.status.label : 'sin dato'} · Termografía ${termoSummary.count ? termoSummary.status.label : 'sin dato'}` : 'Aun no existen mediciones registradas para este activo.', icon: 'fa-shield-heart', tone: overallStatus.tone }),
        crearTarjetaResumenFicha({ label: 'Ultima vibración', value: vibSummary.latest ? `${numeroFicha(vibSummary.latest.valor, 2)} ${vibSummary.latest.unidad || 'mm/s'}` : 'Sin dato', meta: vibSummary.latest ? `${formatearFechaFicha(vibSummary.latest.fecha)} · ${vibSummary.latest.punto_medicion || 'General'}` : 'Sin lecturas de vibración.', icon: 'fa-wave-square', tone: vibSummary.count ? vibSummary.status.tone : '' }),
        crearTarjetaResumenFicha({ label: 'Ultima termografía', value: termoSummary.latest ? `${numeroFicha(termoSummary.latest.valor, 1)} ${termoSummary.latest.unidad || '°C'}` : 'Sin dato', meta: termoSummary.latest ? `${formatearFechaFicha(termoSummary.latest.fecha)} · ${termoSummary.latest.punto_medicion || 'General'}` : 'Sin lecturas térmicas.', icon: 'fa-temperature-three-quarters', tone: termoSummary.count ? termoSummary.status.tone : '' }),
        crearTarjetaResumenFicha({ label: 'Intervenciones', value: numeroFicha(tareasRelacionadas.length), meta: ultimaActividad ? `Ultimo cierre: ${formatearFechaFicha(ultimaActividad.created_at || ultimaActividad.fecha_termino || ultimaActividad.fecha_inicio)}` : 'Sin cierres registrados en historial.', icon: 'fa-screwdriver-wrench' }),
        crearTarjetaResumenFicha({ label: 'Componentes', value: numeroFicha(siblingEquipos.length), meta: siblingEquipos.length > 1 ? 'Hay otros componentes del mismo activo en la unidad.' : 'Activo sin componentes adicionales visibles en la unidad.', icon: 'fa-gears' })
    ].join('');
    document.getElementById('ficha-resumen-vibracion').innerHTML = vibSummary.count ? [crearTarjetaMiniFicha({ label: 'Tendencia', value: vibSummary.trend.label, meta: vibSummary.trend.meta }), crearTarjetaMiniFicha({ label: 'Promedio', value: `${numeroFicha(vibSummary.avg, 2)} mm/s`, meta: `${numeroFicha(vibSummary.count)} lectura(s) en el rango` }), crearTarjetaMiniFicha({ label: 'Maximo', value: `${numeroFicha(vibSummary.max, 2)} mm/s`, meta: `Estado actual: ${vibSummary.status.label}` })].join('') : emptyFichaState('Sin vibraciones registradas', 'Cuando se agreguen lecturas de vibración aparecerán aqui con tendencia, promedio y maximo.');
    document.getElementById('ficha-resumen-termografia').innerHTML = termoSummary.count ? [crearTarjetaMiniFicha({ label: 'Tendencia', value: termoSummary.trend.label, meta: termoSummary.trend.meta }), crearTarjetaMiniFicha({ label: 'Promedio', value: `${numeroFicha(termoSummary.avg, 1)} °C`, meta: `${numeroFicha(termoSummary.count)} lectura(s) en el rango` }), crearTarjetaMiniFicha({ label: 'Maximo', value: `${numeroFicha(termoSummary.max, 1)} °C`, meta: `Estado actual: ${termoSummary.status.label}` })].join('') : emptyFichaState('Sin termografía registrada', 'Cuando se agreguen lecturas térmicas aparecerán aqui con tendencia, promedio y maximo.');
    document.getElementById('lista-mediciones-vibracion').innerHTML = vibs.length ? vibs.slice(0, 6).map(item => renderLecturaFicha(item, 'vibracion')).join('') : emptyFichaState('Sin vibraciones recientes', 'No hay lecturas de vibración para este equipo en el rango disponible.');
    document.getElementById('lista-mediciones-termografia').innerHTML = termos.length ? termos.slice(0, 6).map(item => renderLecturaFicha(item, 'termografia')).join('') : emptyFichaState('Sin inspecciones térmicas', 'Aun no se registran inspecciones térmicas para este equipo.');
    document.getElementById('lista-mediciones-lubricacion').innerHTML = lubs.length ? lubs.slice(0, 6).map(item => `<article id="med-${item.id}" class="planify-ficha-reading"><div class="planify-ficha-reading-top"><div><div class="planify-ficha-reading-title">${item.punto_medicion || 'Actividad de lubricación'}</div><div class="planify-ficha-reading-meta"><span><i class="fa-regular fa-calendar"></i> ${formatearFechaHoraFicha(item.fecha)}</span><span><i class="fa-solid fa-user-gear"></i> ${escapeHtml(getNombresTecnicosFicha(item).join(', ') || 'Sin técnico')}</span></div></div><div class="planify-ficha-reading-value">${item.valor || 'Registro'}</div></div><div style="display:flex;justify-content:space-between;gap:.75rem;align-items:flex-start;"><div class="planify-ficha-reading-note">${item.observaciones || 'Sin observaciones registradas.'}</div><button onclick="window._borrarMedicion('${item.id}')" title="Eliminar medición" style="background:none;border:none;cursor:pointer;color:#94a3b8;padding:2px 4px;font-size:0.84rem;line-height:1;" onmouseover="this.style.color='#ef4444'" onmouseout="this.style.color='#94a3b8'"><i class="fa-solid fa-trash"></i></button></div></article>`).join('') : emptyFichaState('Sin cambios de aceite o engrase', 'Esta pestaña mostrará registros de lubricación cuando existan.');
    document.getElementById('ficha-actividad-trabajos').innerHTML = tareasRelacionadas.length ? tareasRelacionadas.map(task => renderActividadFicha(task, equipo)).join('') : emptyFichaState('Sin cierres relacionados', 'No se encontraron trabajos finalizados asociados a este activo.');
    document.getElementById('ficha-componentes-relacionados').innerHTML = siblingEquipos.length ? siblingEquipos.map(item => renderComponenteRelacionadoFicha(item, medicionesGrupo, siblingIds)).join('') : emptyFichaState('Sin componentes relacionados', 'No se encontraron otros componentes del mismo activo en esta unidad.');
    cargarAvisosSapDeFicha(equipo);
    document.getElementById('ficha-vib-subtitulo').textContent = vibSummary.count ? `${numeroFicha(vibSummary.count)} lectura(s) registradas para ${equipo.componente || equipo.activo}.` : 'No hay tendencia suficiente para este componente.';
    document.getElementById('ficha-termo-subtitulo').textContent = termoSummary.count ? `${numeroFicha(termoSummary.count)} inspección(es) térmicas registradas para ${equipo.componente || equipo.activo}.` : 'No hay tendencia térmica disponible para este componente.';
}

// Carga los avisos SAP vinculados a un equipo y los renderiza en la pestaña
// "Avisos SAP" de su ficha técnica. Vincula por equipo_id (FK) y como
// respaldo también por ubicacion_tecnica/kks.
async function cargarAvisosSapDeFicha(equipo) {
    const lista = document.getElementById('ficha-avisos-list');
    const badge = document.getElementById('ficha-avisos-badge');
    const linkIr = document.getElementById('ficha-ir-avisos');
    if (linkIr) linkIr.onclick = (e) => {
        e.preventDefault();
        document.getElementById('modal-ficha-tecnica')?.remove();
        document.getElementById('nav-avisos')?.click();
    };
    if (!lista) return;
    if (!equipo || !window.supabaseClient) {
        lista.innerHTML = `<p style="color:#94a3b8; padding:1rem; text-align:center; margin:0;">No disponible.</p>`;
        return;
    }
    try {
        const utKeys = [...new Set([equipo.ubicacion_tecnica, equipo.kks].filter(Boolean))];
        // 1) Trae los vinculados por equipo_id
        let avisos = [];
        if (equipo.id) {
            const { data, error } = await window.supabaseClient.from('avisos_sap')
                .select('*').eq('equipo_id', equipo.id);
            if (error) throw error;
            avisos = data || [];
        }
        // 2) Suma los matcheados por UT/KKS (sin duplicar)
        if (utKeys.length) {
            const { data, error } = await window.supabaseClient.from('avisos_sap')
                .select('*').in('ubicacion_tecnica', utKeys);
            if (error) throw error;
            const yaIds = new Set(avisos.map(a => a.id));
            for (const a of (data || [])) if (!yaIds.has(a.id)) avisos.push(a);
        }
        avisos.sort((a, b) => String(b.fecha_notif || '').localeCompare(String(a.fecha_notif || '')));

        if (badge) {
            if (avisos.length) { badge.style.display = ''; badge.textContent = avisos.length; }
            else badge.style.display = 'none';
        }
        if (!avisos.length) {
            lista.innerHTML = `<p style="color:#94a3b8; padding:1rem; text-align:center; margin:0;"><i class="fa-regular fa-bell-slash"></i> Sin avisos SAP registrados para este equipo.</p>`;
            return;
        }
        const fmtFecha = (s) => {
            if (!s) return '—';
            const m = String(s).match(/^(\d{4})-(\d{2})-(\d{2})/);
            return m ? `${m[3]}-${m[2]}-${m[1]}` : String(s);
        };
        const pillAbc = (v) => {
            const colores = { A: ['#fef2f2','#b91c1c'], B: ['#fffbeb','#b45309'], C: ['#ecfdf5','#047857'] };
            const [bg, fg] = colores[v] || ['#f1f5f9','#475569'];
            return `<span style="background:${bg}; color:${fg}; border-radius:999px; padding:0.15rem 0.55rem; font-size:0.7rem; font-weight:800; text-transform:uppercase;">${escapeHtml(v || '—')}</span>`;
        };
        const pillStatus = (v) => {
            const first = String(v || '').split(/\s+/)[0];
            const colores = { CRTD: ['#eff6ff','#1d4ed8'], OUTR: ['#f3f4f6','#4b5563'], TOPV: ['#ecfdf5','#047857'] };
            const [bg, fg] = colores[first] || ['#f1f5f9','#475569'];
            return `<span style="background:${bg}; color:${fg}; border-radius:999px; padding:0.15rem 0.55rem; font-size:0.7rem; font-weight:800;">${escapeHtml(v || '—')}</span>`;
        };
        lista.innerHTML = avisos.map(a => `
            <article style="border:1px solid #e5e7eb; border-radius:12px; padding:0.85rem 1rem; background:#fff;">
                <div style="display:flex; align-items:center; justify-content:space-between; gap:0.5rem; margin-bottom:0.4rem; flex-wrap:wrap;">
                    <div style="display:flex; align-items:center; gap:0.45rem; flex-wrap:wrap;">
                        <span style="font-family: ui-monospace, SFMono-Regular, Menlo, monospace; font-size:0.86rem; font-weight:800; color:#0369a1;">#${escapeHtml(a.nro_notificacion)}</span>
                        ${pillAbc(a.indicador_abc)}
                        ${pillStatus(a.status_usuario)}
                        ${a.parada ? '<span style="background:#fef2f2; color:#b91c1c; border:1px solid #fecaca; border-radius:999px; padding:0.15rem 0.55rem; font-size:0.7rem; font-weight:800;"><i class="fa-solid fa-triangle-exclamation"></i> PARADA</span>' : ''}
                    </div>
                    <span style="font-size:0.8rem; color:#64748b;"><i class="fa-regular fa-calendar"></i> ${fmtFecha(a.fecha_notif)}</span>
                </div>
                <div style="font-size:0.95rem; color:#0f172a; font-weight:600; margin-bottom:0.3rem;">${escapeHtml(a.descripcion_original || 'Sin descripción')}</div>
                <div style="font-size:0.78rem; color:#64748b; display:flex; gap:0.85rem; flex-wrap:wrap;">
                    <span><i class="fa-solid fa-flag"></i> ${escapeHtml(a.prioridad || '—')}</span>
                    <span><i class="fa-solid fa-tag"></i> ${escapeHtml(a.clase_aviso || '—')}</span>
                    <span><i class="fa-solid fa-users-gear"></i> ${escapeHtml(a.pto_trabajo || '—')}</span>
                    ${a.orden ? `<span><i class="fa-solid fa-hashtag"></i> OT ${escapeHtml(a.orden)}</span>` : ''}
                    ${a.autor ? `<span><i class="fa-solid fa-user-pen"></i> ${escapeHtml(a.autor)}</span>` : ''}
                </div>
            </article>
        `).join('');
    } catch (e) {
        console.error('[ficha] avisos:', e);
        lista.innerHTML = `<p style="color:#dc2626; padding:1rem; text-align:center; margin:0;">Error cargando avisos: ${e.message}</p>`;
    }
}

function renderListasFicha(equipo, medicionesEquipo, medicionesGrupo, tareasRelacionadas, fuenteMediciones) {
    // 1º técnico desde la ejecución de ruta (las mediciones de ruta no guardan
    // técnico en la tabla, lo heredan de la ruta asignada); 2º desde tareas.
    medicionesEquipo = completarTecnicosBombasEmergenciaFicha(medicionesEquipo, equipo);
    medicionesEquipo = enriquecerMedicionesConRutaFicha(medicionesEquipo, equipo);
    medicionesGrupo = enriquecerMedicionesConRutaFicha(medicionesGrupo, equipo);
    medicionesEquipo = enriquecerMedicionesConTecnicosFicha(medicionesEquipo, tareasRelacionadas);
    medicionesGrupo = enriquecerMedicionesConTecnicosFicha(medicionesGrupo, tareasRelacionadas);
    const vibs = medicionesEquipo.filter(m => m.tipo === 'vibracion').sort((a, b) => new Date(b.fecha) - new Date(a.fecha));
    const termos = medicionesEquipo.filter(m => m.tipo === 'termografia').sort((a, b) => new Date(b.fecha) - new Date(a.fecha));
    const lubs = medicionesEquipo.filter(m => m.tipo === 'lubricacion').sort((a, b) => new Date(b.fecha) - new Date(a.fecha));
    const siblingEquipos = estado.equipos.filter(item => item.activo === equipo.activo && item.ubicacion === equipo.ubicacion);
    const siblingIds = new Set(siblingEquipos.map(item => String(item.id)));
    const vibSummary = obtenerResumenMedicionesFicha(medicionesEquipo, 'vibracion');
    const termoSummary = obtenerResumenMedicionesFicha(medicionesEquipo, 'termografia');
    const overallStatus = consolidarEstadoFicha([vibSummary.count ? vibSummary.status : null, termoSummary.count ? termoSummary.status : null].filter(Boolean));
    const ultimaActividad = tareasRelacionadas[0] || null;
    const pulsoActivo = getPulsoActivoFicha(equipo, { vibracion: vibSummary, termografia: termoSummary }, tareasRelacionadas);
    const brechaVib = getBrechaUmbralFicha('vibracion', vibSummary);
    const brechaTermo = getBrechaUmbralFicha('termografia', termoSummary);
    const comparativaVib = getComparativaGrupoFicha(equipo, siblingEquipos, medicionesGrupo, 'vibracion');
    const comparativaTermo = getComparativaGrupoFicha(equipo, siblingEquipos, medicionesGrupo, 'termografia');
    const comparativaTone = priorizarToneFicha(comparativaVib.tone, comparativaTermo.tone);
    const comparativaValue = comparativaVib.value !== 'Sin dato'
        ? `Vib ${comparativaVib.value}`
        : (comparativaTermo.value !== 'Sin dato' ? `Temp ${comparativaTermo.value}` : numeroFicha(siblingEquipos.length));
    const comparativaMeta = [
        comparativaVib.value !== 'Sin dato' ? `Vibracion: ${comparativaVib.meta}` : '',
        comparativaTermo.value !== 'Sin dato' ? `Termografia: ${comparativaTermo.meta}` : ''
    ].filter(Boolean).join(' / ') || (siblingEquipos.length > 1
        ? 'Hay componentes hermanos, pero aun no existe una base comparable.'
        : 'Activo sin componentes comparables en esta unidad.');
    const totalLecturas = vibSummary.count + termoSummary.count + lubs.length;

    const critStyles = {
        A: { text: 'Criticidad A', bg: '#fef2f2', color: '#b91c1c', border: '#fecaca' },
        B: { text: 'Criticidad B', bg: '#fff7ed', color: '#b45309', border: '#fdba74' },
        C: { text: 'Criticidad C', bg: '#ecfdf5', color: '#047857', border: '#a7f3d0' }
    };
    const crit = critStyles[equipo.criticidad] || { text: equipo.criticidad || 'Sin criticidad', bg: '#f8fafc', color: '#475569', border: '#cbd5e1' };
    const badgeCrit = document.getElementById('ficha-equipo-criticidad');
    badgeCrit.className = 'badge';
    badgeCrit.textContent = crit.text;
    badgeCrit.style.background = crit.bg;
    badgeCrit.style.color = crit.color;
    badgeCrit.style.border = `1px solid ${crit.border}`;
    document.getElementById('ficha-equipo-nombre').textContent = `${equipo.activo}${equipo.componente ? ' - ' + equipo.componente : ''}`;
    document.getElementById('ficha-equipo-ubicacion').textContent = equipo.ubicacion || 'Sin ubicacion';
    document.getElementById('ficha-equipo-kks').textContent = equipo.kks || 'N/A';
    document.getElementById('ficha-equipo-breadcrumb').innerHTML = `<span>Control</span><i class="fa-solid fa-angle-right"></i><span>${equipo.ubicacion || 'Sin unidad'}</span><i class="fa-solid fa-angle-right"></i><strong>${equipo.activo}</strong>${equipo.componente ? `<i class="fa-solid fa-angle-right"></i><span>${equipo.componente}</span>` : ''}`;
    document.getElementById('ficha-equipo-extra').innerHTML = [
        equipo.denominacion_ut ? `<span><i class="fa-solid fa-tag"></i> ${equipo.denominacion_ut}</span>` : '',
        equipo.frecuencia_nueva ? `<span><i class="fa-solid fa-clock-rotate-left"></i> Frecuencia: ${equipo.frecuencia_nueva} dias</span>` : '',
        equipo.ruta ? `<span><i class="fa-solid fa-route"></i> ${equipo.ruta}</span>` : '',
        equipo.ubicacion_tecnica ? `<span><i class="fa-solid fa-diagram-project"></i> ${equipo.ubicacion_tecnica}</span>` : ''
    ].filter(Boolean).join('');

    const sourceEl = document.getElementById('ficha-equipo-source');
    const sourceMap = {
        online: '<i class="fa-solid fa-cloud-arrow-down"></i> Datos online',
        estado: '<i class="fa-solid fa-bolt"></i> Cache de sesion',
        local: '<i class="fa-solid fa-hard-drive"></i> Cache local',
        none: '<i class="fa-solid fa-circle-info"></i> Sin mediciones'
    };
    sourceEl.innerHTML = sourceMap[fuenteMediciones] || sourceMap.none;
    sourceEl.style.display = 'inline-flex';

    document.getElementById('ficha-equipo-actions').innerHTML = `
        <button class="btn btn-outline planify-ficha-action-btn" onclick="window.irAHistorialDeEquipo('${equipo.id}')"><i class="fa-solid fa-clock-rotate-left"></i> Historial</button>
        <button class="btn btn-outline planify-ficha-action-btn" onclick="window.irAControlConBusqueda('${equipo.id}')"><i class="fa-solid fa-magnifying-glass"></i> Buscar</button>
        <button class="btn btn-outline planify-ficha-action-btn" onclick="window.abrirVistaUnidad('${String(equipo.ubicacion || '').replace(/'/g, "\\'")}')"><i class="fa-solid fa-location-dot"></i> Unidad</button>
    `;

    const lubricantesEquipo = (window.PLANIFY_ACEITES && window.PLANIFY_ACEITES.get(equipo)) || null;

    document.getElementById('ficha-equipo-overview').innerHTML = [
        renderTarjetaAceiteFicha(lubricantesEquipo),
        crearTarjetaResumenFicha({ label: 'Estado actual', value: overallStatus.label, meta: vibSummary.count || termoSummary.count ? `Vibracion ${vibSummary.count ? vibSummary.status.label : 'sin dato'} / Termografia ${termoSummary.count ? termoSummary.status.label : 'sin dato'}` : 'Aun no existen mediciones registradas para este activo.', icon: 'fa-shield-heart', tone: overallStatus.tone }),
        crearTarjetaResumenFicha({ label: 'Pulso del activo', value: pulsoActivo.value, meta: pulsoActivo.meta, icon: 'fa-heart-pulse', tone: pulsoActivo.tone }),
        crearTarjetaResumenFicha({ label: 'Ultima vibracion', value: vibSummary.latest ? `${numeroFicha(vibSummary.latest.valor, 2)} ${vibSummary.latest.unidad || 'mm/s'}` : 'Sin dato', meta: vibSummary.latest ? `${formatearFechaFicha(vibSummary.latest.fecha)} / ${vibSummary.latest.punto_medicion || 'General'} / ${vibSummary.status.label}` : 'Sin lecturas de vibracion.', icon: 'fa-wave-square', tone: vibSummary.count ? vibSummary.status.tone : '' }),
        crearTarjetaResumenFicha({ label: 'Ultima termografia', value: termoSummary.latest ? `${numeroFicha(termoSummary.latest.valor, 1)} ${termoSummary.latest.unidad || 'C'}` : 'Sin dato', meta: termoSummary.latest ? `${formatearFechaFicha(termoSummary.latest.fecha)} / ${termoSummary.latest.punto_medicion || 'General'} / ${termoSummary.status.label}` : 'Sin lecturas termicas.', icon: 'fa-temperature-three-quarters', tone: termoSummary.count ? termoSummary.status.tone : '' }),
        crearTarjetaResumenFicha({ label: 'Intervenciones', value: numeroFicha(tareasRelacionadas.length), meta: ultimaActividad ? `Ultimo cierre: ${formatearFechaFicha(ultimaActividad.created_at || ultimaActividad.fecha_termino || ultimaActividad.fecha_inicio)} / ${numeroFicha(totalLecturas)} lectura(s) asociadas` : `${numeroFicha(totalLecturas)} lectura(s) en el historial del activo.`, icon: 'fa-screwdriver-wrench' }),
        crearTarjetaResumenFicha({ label: 'Comparativa del activo', value: comparativaValue, meta: comparativaMeta, icon: 'fa-code-compare', tone: comparativaTone })
    ].join('');

    const especAceite = document.getElementById('ficha-aceite-especificacion');
    if (especAceite) {
        especAceite.innerHTML = lubricantesEquipo
            ? `<div class="planify-ficha-card"><div class="planify-ficha-card-head"><div>
                    <h3><i class="fa-solid fa-oil-can" style="color:#b45309;"></i> Aceite / lubricante del equipo</h3>
                    <span>Tipo de aceite y cantidad según planilla de lubricación.</span>
                </div></div>
                <div class="planify-aceite-lista" style="margin-top:.5rem;">${_lubricantesFilasFicha(lubricantesEquipo)}</div>
               </div>`
            : '';
    }

    document.getElementById('ficha-resumen-vibracion').innerHTML = vibSummary.count ? [
        crearTarjetaMiniFicha({ label: 'Tendencia', value: vibSummary.trend.label, meta: vibSummary.trend.meta, tone: vibSummary.trend.className }),
        crearTarjetaMiniFicha({ label: 'Promedio', value: `${numeroFicha(vibSummary.avg, 2)} mm/s`, meta: `${numeroFicha(vibSummary.count)} lectura(s) en el rango`, tone: vibSummary.status.tone }),
        crearTarjetaMiniFicha({ label: 'Maximo', value: `${numeroFicha(vibSummary.max, 2)} mm/s`, meta: `Estado actual: ${vibSummary.status.label}`, tone: getEstadoCondicionFicha('vibracion', vibSummary.max).tone }),
        crearTarjetaMiniFicha({ label: 'Brecha al umbral', value: brechaVib.value, meta: brechaVib.meta, tone: brechaVib.tone })
    ].join('') : emptyFichaState('Sin vibraciones registradas', 'Cuando se agreguen lecturas de vibracion apareceran aqui con tendencia, promedio, maximo y brecha al umbral.');

    document.getElementById('ficha-resumen-termografia').innerHTML = termoSummary.count ? [
        crearTarjetaMiniFicha({ label: 'Tendencia', value: termoSummary.trend.label, meta: termoSummary.trend.meta, tone: termoSummary.trend.className }),
        crearTarjetaMiniFicha({ label: 'Promedio', value: `${numeroFicha(termoSummary.avg, 1)} C`, meta: `${numeroFicha(termoSummary.count)} lectura(s) en el rango`, tone: termoSummary.status.tone }),
        crearTarjetaMiniFicha({ label: 'Maximo', value: `${numeroFicha(termoSummary.max, 1)} C`, meta: `Estado actual: ${termoSummary.status.label}`, tone: getEstadoCondicionFicha('termografia', termoSummary.max).tone }),
        crearTarjetaMiniFicha({ label: 'Brecha al umbral', value: brechaTermo.value, meta: brechaTermo.meta, tone: brechaTermo.tone })
    ].join('') : emptyFichaState('Sin termografia registrada', 'Cuando se agreguen lecturas termicas apareceran aqui con tendencia, promedio, maximo y brecha al umbral.');

    document.getElementById('lista-mediciones-vibracion').innerHTML = vibs.length ? vibs.slice(0, 6).map(item => renderLecturaFicha(item, 'vibracion')).join('') : emptyFichaState('Sin vibraciones recientes', 'No hay lecturas de vibracion para este equipo en el rango disponible.');
    document.getElementById('lista-mediciones-termografia').innerHTML = termos.length ? termos.slice(0, 6).map(item => renderLecturaFicha(item, 'termografia')).join('') : emptyFichaState('Sin inspecciones termicas', 'Aun no se registran inspecciones termicas para este equipo.');

    // Excitatriz: historial de termografías de carbones (escobillas) como tarjetas.
    const excitatrizCont = document.getElementById('ficha-termo-excitatriz');
    if (excitatrizCont) {
        const esEquipoExc = /excitatriz|escobilla|carbon/i.test(`${equipo.activo || ''} ${equipo.componente || ''}`)
            || (tareasRelacionadas || []).some(t => esTrabajoTermografia(t));
        const trabajosExc = esEquipoExc
            ? (tareasRelacionadas || [])
                .filter(t => esTrabajoTermografia(t))
                .sort((a, b) => new Date(b.fecha_termino || b.created_at || 0) - new Date(a.fecha_termino || a.created_at || 0))
            : [];
        excitatrizCont.innerHTML = renderFichaTermoExcitatriz(trabajosExc, esEquipoExc);
    }
    window._planifyFichaTiristoresEquipo = equipo;
    renderFichaTiristoresPanel(equipo);
document.getElementById('lista-mediciones-lubricacion').innerHTML = lubs.length ? lubs.slice(0, 6).map(item => `<article id="med-${item.id}" class="planify-ficha-reading"><div class="planify-ficha-reading-top"><div><div class="planify-ficha-reading-title">${item.punto_medicion || 'Actividad de lubricacion'}</div><div class="planify-ficha-reading-meta"><span><i class="fa-regular fa-calendar"></i> ${formatearFechaHoraFicha(item.fecha)}</span><span><i class="fa-solid fa-user-gear"></i> ${escapeHtml(getNombresTecnicosFicha(item).join(', ') || 'Sin técnico')}</span></div></div><div class="planify-ficha-reading-value">${item.valor || 'Registro'}</div></div><div style="display:flex;justify-content:space-between;gap:.75rem;align-items:flex-start;"><div class="planify-ficha-reading-note">${item.observaciones || 'Sin observaciones registradas.'}</div><button onclick="window._borrarMedicion('${item.id}')" title="Eliminar medicion" style="background:none;border:none;cursor:pointer;color:#94a3b8;padding:2px 4px;font-size:0.84rem;line-height:1;" onmouseover="this.style.color='#ef4444'" onmouseout="this.style.color='#94a3b8'"><i class="fa-solid fa-trash"></i></button></div></article>`).join('') : emptyFichaState('Sin cambios de aceite o engrase', 'Esta pestana mostrara registros de lubricacion cuando existan.');
    document.getElementById('ficha-actividad-trabajos').innerHTML = tareasRelacionadas.length ? tareasRelacionadas.map(task => renderActividadFicha(task, equipo)).join('') : emptyFichaState('Sin cierres relacionados', 'No se encontraron trabajos finalizados asociados a este activo.');
    document.getElementById('ficha-componentes-relacionados').innerHTML = siblingEquipos.length ? siblingEquipos.map(item => renderComponenteRelacionadoFicha(item, medicionesGrupo, siblingIds)).join('') : emptyFichaState('Sin componentes relacionados', 'No se encontraron otros componentes del mismo activo en esta unidad.');
    cargarAvisosSapDeFicha(equipo);
    document.getElementById('ficha-vib-subtitulo').textContent = vibSummary.count ? `${numeroFicha(vibSummary.count)} lectura(s) registradas / ultima ${String(vibSummary.status.label || '').toLowerCase()} / pico ${numeroFicha(vibSummary.max, 2)} mm/s.` : 'No hay tendencia suficiente para este componente.';
    document.getElementById('ficha-termo-subtitulo').textContent = termoSummary.count ? `${numeroFicha(termoSummary.count)} lectura(s) termicas / ultima ${String(termoSummary.status.label || '').toLowerCase()} / pico ${numeroFicha(termoSummary.max, 1)} C.` : 'No hay tendencia termica disponible para este componente.';
}

// Tarjetas de termografía de carbones (escobillas) para la pestaña Termografía
// de la ficha. Cada trabajo es expandible al detalle de escobillas + descarga.
function renderFichaTermoExcitatriz(trabajos, esEquipoExc) {
    if (!esEquipoExc) return '';
    if (!trabajos || !trabajos.length) {
        return `<div class="planify-ficha-card">
            <div class="planify-ficha-card-head"><div>
                <h3><i class="fa-solid fa-bolt-lightning" style="color:#dc2626;"></i> Termografías de carbones</h3>
                <span>Las inspecciones de escobillas iran apareciendo aqui a medida que se cierren.</span>
            </div></div>
            ${emptyFichaState('Sin termografias de carbones', 'Cuando se finalice una termografia de escobillas, se vera aqui como tarjeta con el detalle de cada carbon.')}
        </div>`;
    }
    const cards = trabajos.slice(0, 8).map(item => {
        const { escobillas, header } = _parseExcitatrizAcciones(item.acciones_realizadas);
        const fecha = _tgFmtFechaLarga(item.fecha_termino || item.created_at);
        const lider = escapeHtml(item.lider_nombre || 'Sin técnico');
        const ot = item.ot_numero ? escapeHtml(String(item.ot_numero)) : '';
        const unidad = obtenerUnidadTarea({ tipo: item.tipo, subtitulo: item.subtitulo, ubicacion: item.ubicacion });
        const puedePlanilla = [3, 4, 5].includes(unidad) && escobillas.length;
        const nAlta = escobillas.filter(e => e.alta === 'SI').length;
        const nNoNorm = escobillas.filter(e => e.norm === 'NO').length;
        const detId = `ficha-exc-det-${escapeHtml(String(item.id))}`;

        const filas = escobillas.map(e => {
            const alta = e.alta === 'SI';
            const normNo = e.norm === 'NO';
            return `<tr style="border-top:1px solid #e5e7eb; ${alta ? 'background:#fef2f2;' : ''}">
                <td style="padding:0.35rem 0.55rem; font-weight:700; color:#475569;">${escapeHtml(e.pos)}</td>
                <td style="padding:0.35rem 0.55rem; text-align:center; ${alta ? 'color:#dc2626; font-weight:700;' : 'color:#0f172a;'}">${escapeHtml(e.temp || '—')}</td>
                <td style="padding:0.35rem 0.55rem; text-align:center; color:#0f172a;">${escapeHtml(e.corr || '—')}</td>
                <td style="padding:0.35rem 0.55rem; text-align:center; font-weight:700; color:${alta ? '#dc2626' : '#94a3b8'};">${escapeHtml(e.alta || '—')}</td>
                <td style="padding:0.35rem 0.55rem; text-align:center; font-weight:700; color:${normNo ? '#b45309' : (e.norm === 'SI' ? '#16a34a' : '#94a3b8')};">${escapeHtml(e.norm || '—')}</td>
            </tr>`;
        }).join('');

        const kpi = (val, label, color) => `<span style="display:inline-flex; flex-direction:column; align-items:center; min-width:54px;">
            <strong style="font-size:1.05rem; color:${color}; line-height:1;">${val}</strong>
            <span style="font-size:0.66rem; color:#64748b; text-transform:uppercase; letter-spacing:0.03em; margin-top:0.15rem;">${label}</span>
        </span>`;

        return `<article style="border:1px solid #fde0d5; border-radius:14px; background:#fff; overflow:hidden; box-shadow:0 4px 12px rgba(220,38,38,0.05);">
            <div style="padding:0.85rem 0.95rem; background:linear-gradient(135deg,#fff7ed 0%,#ffffff 70%); border-bottom:1px solid #f1f5f9;">
                <div style="display:flex; justify-content:space-between; align-items:flex-start; gap:0.6rem;">
                    <div>
                        <div style="font-weight:800; color:#0f172a; font-size:0.95rem;"><i class="fa-regular fa-calendar-check" style="color:#dc2626;"></i> ${escapeHtml(fecha)}</div>
                        <div style="font-size:0.8rem; color:#64748b; margin-top:0.2rem;"><i class="fa-solid fa-user-gear"></i> ${lider}${ot ? ` &nbsp;·&nbsp; <i class="fa-solid fa-clipboard-list"></i> OT ${ot}` : ''}</div>
                    </div>
                </div>
                <div style="display:flex; gap:0.6rem; margin-top:0.7rem;">
                    ${kpi(escobillas.length, 'mediciones', '#0f172a')}
                    ${kpi(nAlta, 'alta temp', nAlta ? '#dc2626' : '#94a3b8')}
                    ${kpi(nNoNorm, 'sin normalizar', nNoNorm ? '#b45309' : '#94a3b8')}
                </div>
            </div>
            <div style="display:flex; gap:0.5rem; padding:0.6rem 0.95rem; flex-wrap:wrap;">
                <button type="button" onclick="window._toggleFichaExcDet('${detId}', this)" style="flex:1; min-width:120px; background:#fff; border:1px solid #e5e7eb; border-radius:9px; padding:0.5rem 0.8rem; font-weight:700; font-size:0.83rem; color:#334155; cursor:pointer; display:inline-flex; align-items:center; justify-content:center; gap:0.4rem;">
                    <i class="fa-solid fa-table-list"></i> Ver detalle
                </button>
                ${puedePlanilla ? `<button type="button" onclick="window.generarPlanillaExcitatrizHistorial('${escapeHtml(String(item.id))}')" style="flex:1; min-width:120px; background:linear-gradient(135deg, #dc2626 0%, #f97316 100%); color:#fff; border:none; border-radius:9px; padding:0.5rem 0.8rem; font-weight:800; font-size:0.83rem; cursor:pointer; display:inline-flex; align-items:center; justify-content:center; gap:0.4rem;">
                    <i class="fa-solid fa-file-arrow-down"></i> Planilla
                </button>` : ''}
            </div>
            <div id="${detId}" style="display:none; padding:0 0.95rem 0.95rem;">
                <div style="display:grid; grid-template-columns:1fr 1fr; gap:0.5rem; margin-bottom:0.6rem; font-size:0.78rem;">
                    <div style="background:#f8fafc; border:1px solid #eef2f7; border-radius:8px; padding:0.4rem 0.55rem;">Hum: <strong>${escapeHtml(header.hum || '—')}%</strong> · Temp: <strong>${escapeHtml(header.temp || '—')}°C</strong></div>
                    <div style="background:#f8fafc; border:1px solid #eef2f7; border-radius:8px; padding:0.4rem 0.55rem;">Gen: <strong>${escapeHtml(header.gen || '—')}MW</strong> · Vc: <strong>${escapeHtml(header.vcampo || '—')}</strong> · Ic: <strong>${escapeHtml(header.icampo || '—')}</strong></div>
                </div>
                ${escobillas.length ? `<div style="overflow-x:auto; border:1px solid #e5e7eb; border-radius:10px;">
                    <table style="width:100%; border-collapse:collapse; font-size:0.8rem; min-width:380px;">
                        <thead><tr style="background:#f8fafc; color:#475569; text-align:left;">
                            <th style="padding:0.45rem 0.55rem;">Escob</th>
                            <th style="padding:0.45rem 0.55rem; text-align:center;">Temp °C</th>
                            <th style="padding:0.45rem 0.55rem; text-align:center;">Corr A</th>
                            <th style="padding:0.45rem 0.55rem; text-align:center;">Alta</th>
                            <th style="padding:0.45rem 0.55rem; text-align:center;">Norm.</th>
                        </tr></thead>
                        <tbody>${filas}</tbody>
                    </table>
                </div>` : `<div style="padding:0.6rem; color:#64748b; font-size:0.85rem;">No se pudieron reconstruir las escobillas de este registro.</div>`}
            </div>
        </article>`;
    }).join('');

    return `<div class="planify-ficha-card">
        <div class="planify-ficha-card-head"><div>
            <h3><i class="fa-solid fa-bolt-lightning" style="color:#dc2626;"></i> Termografías de carbones</h3>
            <span>Ultimas inspecciones de escobillas. Toca "Ver detalle" para las mediciones de cada carbon.</span>
        </div></div>
        <div style="display:grid; grid-template-columns:repeat(auto-fill,minmax(280px,1fr)); gap:0.85rem; margin-top:0.6rem;">${cards}</div>
    </div>`;
}

window._toggleFichaExcDet = function(detId, btn) {
    const el = document.getElementById(detId);
    if (!el) return;
    const abierto = el.style.display !== 'none';
    el.style.display = abierto ? 'none' : 'block';
    if (btn) btn.innerHTML = abierto
        ? '<i class="fa-solid fa-table-list"></i> Ver detalle'
        : '<i class="fa-solid fa-chevron-up"></i> Ocultar detalle';
};

window.abrirFichaTecnica = async function(equipoId) {
    const equipo = estado.equipos.find(item => String(item.id) === String(equipoId));
    if (!equipo) return;

    renderFichaTecnicaModal();
    const modal = document.getElementById('modal-ficha-tecnica');
    if (!modal) return;

    const siblingEquipos = estado.equipos.filter(item =>
        item.activo === equipo.activo && item.ubicacion === equipo.ubicacion
    );
    const siblingIds = siblingEquipos.length
        ? siblingEquipos.map(item => item.id)
        : [equipo.id];

    const getMedEquipoId = med => med?.equipo_id ?? med?.equipoId ?? null;
    const normalize = value => String(value || '').trim().toLowerCase();
    const idsSet = new Set(siblingIds.map(id => String(id)));
    const filtroGrupo = items => (items || []).filter(med => idsSet.has(String(getMedEquipoId(med))));

    renderFichaLoadingState(equipo);
    modal.style.display = 'flex';
    setupFichaEvents();

    let medicionesGrupo = [];
    let fuenteMediciones = 'none';

    if (navigator.onLine && supabaseClient) {
        const tablas = [...new Set([tablasDb.mediciones, 'mediciones', 'historial_mediciones'].filter(Boolean))];
        for (const tabla of tablas) {
            try {
                const { data, error } = await supabaseClient
                    .from(tabla)
                    .select('*')
                    .in('equipo_id', siblingIds)
                    .order('fecha', { ascending: false })
                    .limit(300);

                if (!error && Array.isArray(data) && data.length) {
                    medicionesGrupo = data;
                    fuenteMediciones = 'online';
                    break;
                }

                if (error && !esErrorTablaNoExiste(error)) {
                    console.warn('[Ficha] Error obteniendo mediciones desde', tabla, error.message);
                }
            } catch (error) {
                console.warn('[Ficha] Error inesperado consultando mediciones:', error);
            }
        }
    }

    if (!medicionesGrupo.length) {
        medicionesGrupo = filtroGrupo(estado.historialMediciones);
        if (medicionesGrupo.length) fuenteMediciones = 'estado';
    }

    if (!medicionesGrupo.length && window.localDB?.mediciones) {
        try {
            const locales = await window.localDB.mediciones.getAll();
            medicionesGrupo = filtroGrupo(locales);
            if (medicionesGrupo.length) fuenteMediciones = 'local';
        } catch (error) {
            console.warn('[Ficha] No fue posible leer mediciones locales:', error);
        }
    }

    let medicionesEquipo = medicionesGrupo.filter(med => String(getMedEquipoId(med)) === String(equipo.id));

    if (!medicionesEquipo.length && equipo.componente) {
        medicionesEquipo = medicionesGrupo.filter(med =>
            normalize(med.componente || med.punto_medicion) === normalize(equipo.componente)
        );
    }

    if (!medicionesEquipo.length) {
        medicionesEquipo = medicionesGrupo.filter(med => {
            const equipoAsociado = estado.equipos.find(item => String(item.id) === String(getMedEquipoId(med)));
            return equipoAsociado &&
                equipoAsociado.activo === equipo.activo &&
                equipoAsociado.ubicacion === equipo.ubicacion;
        });
    }

    const tareasRelacionadas = getTareasRelacionadasFicha(equipo, siblingIds);
    renderListasFicha(equipo, medicionesEquipo, medicionesGrupo, tareasRelacionadas, fuenteMediciones);

    setTimeout(() => {
        initFichaCharts(medicionesEquipo);
        initFichaTiristoresCharts();
    }, 40);

    // Exponer mediciones del grupo para el visor 3D (usadas por el popup al clickear escobillas).
    // Enriquecemos con técnicos desde tareas relacionadas — mismo paso que hace la pestaña Termografía.
    const medsParaVision3D = enriquecerMedicionesConTecnicosFicha(medicionesGrupo, tareasRelacionadas);
    window._planifyFichaMediciones = medsParaVision3D;
    if (window._planifyVision3DApi && typeof window._planifyVision3DApi.setMediciones === 'function') {
        window._planifyVision3DApi.setMediciones(medsParaVision3D);
    }
};

